#!/usr/bin/env node
/**
 * 看板生成器(零依赖;ddd-kanban plugin 版,配置来自看板目录下 kanban.config.json)。
 *
 *   node scripts/gen.mjs --dir <kanbanDir>   # 缺省:$CLAUDE_PROJECT_DIR/app/kanban,或 cwd(若含 kanban.config.json)
 *   python3 <kanbanDir>/serve.py             # 服务化(:config.port, no-cache),refs/ 文档可点开
 *
 * 做三件事:
 *   1. 读 manifest.json(进度看板)+ backlog-manifest.json(backlog),各自校验。
 *   2. 把开发文档(config.docs)用内置零依赖 md 渲染器渲染进 kanban/refs/*.html
 *      (带返回栏 / 统一样式 / 目录 / 锚点),供卡片站内链接,避免 ../docs/*.md 逃出根 404。
 *      type:"html" 条目(自包含 HTML 指南)不走渲染:源文件原样复制进 refs/,源留原地不动。
 *   3. 写自包含 index.html:[进度看板] / [决策路径] / [决策/Demo] / [Backlog] / [文档库] tab;
 *      决策 tab 带筛选/排序工具条,文档库是四段 Hub(D46);卡片里
 *      文档链接 → refs/ 渲染页,代码/数据链接 → GitHub blob,commit → GitHub commit。
 *
 * 改任一 manifest 或被引用文档后重跑;refs/*.html 与 index.html 都提交进 git。
 */
import { readFileSync, writeFileSync, copyFileSync, mkdirSync, readdirSync, rmSync, statSync, existsSync } from 'node:fs'
import { execFileSync } from 'node:child_process'
import { join, relative, sep } from 'node:path'
import { cmpVer, readPluginVersion, readStamp } from './lib-version.mjs'
import { genStrings } from './strings.mjs'
import { declaredPrs, prsOfCard } from './prlink.mjs'
import { resolveKanbanDir } from './kanban-dir.mjs'
import { relIndex, stageOf } from './relstage.mjs'
import { lite, litePreview } from './lite.mjs'
import { dormantDate, settleHold, settleOf, staleLink } from './settle.mjs'
import { CARD_KINDS, cardsDirOf, scanCardDir, sortCards, stripOrder } from './cards.mjs'

// ---- 看板目录定位:--dir <kanbanDir> > $CLAUDE_PROJECT_DIR/app/kanban > cwd(若含 kanban.config.json)----
// v0.12.0 起抽进 kanban-dir.mjs,与 pr-sync.mjs 共用(两个脚本必须认同一个 --dir)。
const HERE = resolveKanbanDir()
const REPO_ROOT = join(HERE, '..', '..') // 项目根(读 docs 用)
const REFS_DIR = join(HERE, 'refs')

// ---- gen 版本戳(防「旧版 session 盖板」)----
// 版本自 ../.claude-plugin/plugin.json(真源);读不到硬失败——必须保证「gen 跑过就一定留戳」,
// 守卫才有「无戳 = 旧 gen 产物 → 重跑自愈」的等价性;放行无戳输出会造出每次收工都重生成的永动。
const GEN_VER = readPluginVersion()
if (!GEN_VER) throw new Error('[gen] 读不到 plugin 自身 .claude-plugin/plugin.json 的 version(或其值非纯数字点分——勿用 -rc/-beta 后缀)——gen.mjs 不应脱离 plugin 目录单跑;修复安装或从 plugin 根运行 / cannot read a plain-numeric "version" from the plugin\'s own .claude-plugin/plugin.json (no -rc/-beta suffixes); do not run gen.mjs outside the plugin directory — repair the install or run from the plugin root')
// 拒降级:现有产物的戳比本 gen 新 → 拒跑(防旧 gen 盖新产物;多半是本 session 的 plugin 旧了)。
// 越过是 human-only 动作:须显式 --force-downgrade=<产物戳版本>(报错文案不提示此旗——
// 守卫会把 stderr 喂回 agent 自修,防线别变教程)。
{
  const prev = readStamp(join(HERE, 'index.html'))
  if (prev && cmpVer(prev, GEN_VER) > 0 && !process.argv.includes(`--force-downgrade=${prev}`)) {
    throw new Error(`[gen] 现有 index.html 由更新的 ddd-gen v${prev} 生成(本 gen 是 v${GEN_VER})——拒绝用旧版覆盖新产物。升级 plugin 或重启 session 后重试。/ Existing index.html was generated by a newer ddd-gen v${prev} (this gen is v${GEN_VER}); refusing to overwrite newer output with an older version. Upgrade the plugin or restart the session, then retry.`)
  }
}

// ---- kanban.config.json(schemaVersion 缺省 1;lang 缺省 zh;port 由 serve.py 消费,gen 不用)----
let cfg
try { cfg = JSON.parse(readFileSync(join(HERE, 'kanban.config.json'), 'utf8')) }
catch (e) { throw new Error(`读不到(cannot read)${join(HERE, 'kanban.config.json')}:${e.message}`) }
const GS = genStrings(cfg.lang === 'en' ? 'en' : 'zh') // gen 硬失败文案表(zh/en;此行以上的硬失败发生在 lang 已知之前,双语合排)
if ((cfg.schemaVersion ?? 1) !== 1) console.warn(`[gen] ⚠ 未知 schemaVersion=${cfg.schemaVersion},按 1 读`)
if (!cfg.brand) throw new Error(GS.cfgMissingBrand())
const BRAND = cfg.brand
const HTML_LANG = (cfg.lang ?? 'zh') === 'zh' ? 'zh-CN' : String(cfg.lang)
const KANBAN_REL = relative(REPO_ROOT, HERE).split(sep).join('/') // 看板目录的 repo-root 相对路径(标准布局 = 'app/kanban')

// ———— config.themeColors(v0.4.0,可选):六套 JS 语义色的浅覆盖 ————
// 这些色以 style="--c:…"/style="background:…" 注入 HTML,样式表(含 theme.css)盖不住,故走 config;
// 形如 {"STATUS_COLOR":{"done":"#146152"},"DOC_SEGMENTS":{"地基":"#146152"}};不给则零行为差。
const TC = cfg.themeColors || {}
{
  const known = ['STATUS_COLOR', 'BL_STATUS_COLOR', 'PRI_COLOR', 'TIER_COLOR', 'DEC_STATUS_COLOR', 'DOC_SEGMENTS']
  for (const k of Object.keys(TC)) if (!known.includes(k)) console.warn(`[gen] ⚠ themeColors 未知色组「${k}」,忽略;合法:${known.join(' / ')}`)
}
const tcMerge = (name, base) => {
  const ov = TC[name] || {}
  for (const k of Object.keys(ov)) if (!(k in base)) console.warn(`[gen] ⚠ themeColors.${name} 未知键「${k}」,忽略`)
  return Object.fromEntries(Object.entries(base).map(([k, v]) => [k, ov[k] ?? v]))
}

const m = JSON.parse(readFileSync(join(HERE, 'manifest.json'), 'utf8'))
const b = JSON.parse(readFileSync(join(HERE, 'backlog-manifest.json'), 'utf8'))
const dm = JSON.parse(readFileSync(join(HERE, 'decisions-manifest.json'), 'utf8'))
// ———— 一卡一文件(v0.14.0,config.cardsDir;未配 = 一切照旧,输出逐字节冻结)————
// 卡从 <cardsDir>/backlog/*.json 与 <cardsDir>/decisions/*.json 逐文件读,头文件只剩表头
// ($comment / instance / statuses / priorities / tiers / groups)。文件按名排序后读,与文件系统顺序无关;
// 显示顺序按拆分写入的 order(= 原数组下标)再按 id —— 数组顺序在这份 gen 里就是显示顺序
// (截图廊组序靠 decisionRank、深链表 LAZY_IDMAP 靠键序、byDateDesc 是稳定排序)。
const CARDS_DIR = cardsDirOf(cfg)
const CARD_SRC = new Map() // id → 卡文件相对看板目录的路径(更新日期与报错点名共用)
if (CARDS_DIR) {
  const seen = new Map()
  for (const kind of CARD_KINDS) {
    const head = kind.key === 'items' ? b : dm
    if (head[kind.key] !== undefined) throw new Error(GS.cardsDirHeadHasItems(kind.manifest, kind.key, CARDS_DIR))
    const rel = `${CARDS_DIR}/${kind.sub}`
    const scan = scanCardDir(join(HERE, CARDS_DIR, kind.sub))
    if (scan.missing) throw new Error(GS.cardsDirMissing(rel))
    for (const x of scan.bad) {
      if (x.kind === 'parse') throw new Error(GS.cardParseFail(`${rel}/${x.file}`, x.message))
      throw new Error(GS.cardIdMismatch(`${rel}/${x.file}`, x.id))
    }
    const list = []
    for (const x of scan.cards) {
      const id = String(x.card.id)
      const prev = seen.get(id)
      if (prev) throw new Error(GS.cardDupId(id, prev, `${rel}/${x.file}`))
      seen.set(id, `${rel}/${x.file}`)
      CARD_SRC.set(id, `${rel}/${x.file}`)
      list.push(x.card)
    }
    head[kind.key] = stripOrder(sortCards(list))
  }
}
// ———— 每卡更新日期(v0.14.0,仅 cardsDir 开)————
// 一条 git log 批量取每个卡文件的最后提交日(不是一卡一条命令);照 docUpdated 的静默降级:
// git 失败 / 文件还没提交 → 文件 mtime → 空。取的是已提交的事实,同一 commit 下同输出,不破确定性。
const CARD_UPDATED = new Map() // id → 'YYYY-MM-DD' | ''
if (CARDS_DIR) {
  const byPath = new Map() // '<sub>/<id>.json' → 最后提交日(git 的路径相对仓根,不相对看板目录,故只认末两段)
  try {
    const out = execFileSync('git', ['log', '--format=%cs', '--name-only', '--', CARDS_DIR],
      { cwd: HERE, stdio: ['ignore', 'pipe', 'ignore'], maxBuffer: 64 * 1024 * 1024 }).toString()
    let day = ''
    for (const raw of out.split('\n')) {
      const line = raw.trim()
      if (!line) continue
      if (/^\d{4}-\d{2}-\d{2}$/.test(line)) { day = line; continue }
      const k = line.split('/').slice(-2).join('/')
      if (day && !byPath.has(k)) byPath.set(k, day) // git log 是新→旧,第一次见到即最后一次改动
    }
  } catch { /* 无 git / 命令失败 → 整批退 mtime */ }
  for (const [id, rel] of CARD_SRC) {
    let d = byPath.get(rel.split('/').slice(-2).join('/')) || ''
    if (!d) { try { d = statSync(join(HERE, rel)).mtime.toISOString().slice(0, 10) } catch { d = '' } }
    CARD_UPDATED.set(id, d)
  }
}
const cardUpd = (id) => CARD_UPDATED.get(id) || ''
// instance.ghRepo/branch 三 manifest 各存一份(现状,避免双真源迁移);不一致仅提醒,不阻断
{
  const three = [['manifest', m], ['backlog-manifest', b], ['decisions-manifest', dm]]
  for (const k of ['ghRepo', 'branch']) {
    if (new Set(three.map(([, x]) => (x.instance || {})[k])).size > 1)
      console.warn(`[gen] ⚠ instance.${k} 三 manifest 不一致:` + three.map(([n, x]) => `${n}=${(x.instance || {})[k]}`).join(' · '))
  }
}
let pm = null // 决策路径叙事(demo 历程 → 拍板项 → C 决策);缺失则不渲染「决策路径」tab
try { pm = JSON.parse(readFileSync(join(HERE, 'path-manifest.json'), 'utf8')) }
catch (e) { console.warn('[gen] ⚠ path-manifest.json 缺失/无效,跳过决策路径 tab:', e.message) }
const DEMOS_DIR = join(HERE, 'demos')

const GH_BLOB = `https://github.com/${m.instance.ghRepo}/blob/${m.instance.branch}/`

// ---- 渲染进 refs/ 的开发文档(config.docs;path 相对 REPO_ROOT;baseDir 解析文档内相对链接)----
const DOC_CATS = ['交接与接手', '设计与决策', '评审与审计', '计划与预案', '环境与指南', '会话日志', '其他']

// ———— 文档库 Hub 四段(D46:地基→流程→操作→存档);category→段名映射,config.docSegments 覆盖 ————
// 段模型是 Hub 设计的固定部分(不做通用 DSL);config 的自定义点 = 哪个 category 归哪段。
const DOC_SEGMENTS = [
  { key: 'fnd', name: '地基', typ: '设计 · 决策', color: '#0f7b6c', desc: '数据模型、口径、决策日志 —— 落 UI 前先站稳' },
  { key: 'prc', name: '流程', typ: '开发 · 协作', color: '#2383e2', desc: '怎么推进:评审、排期、接手' },
  { key: 'ops', name: '操作', typ: '部署 · 环境', color: '#b7791f', desc: '跑起来 / 部署 / 环境' },
  { key: 'arc', name: '存档', typ: 'journal · 历史', color: '#a8a29e', desc: '会话日志与杂项,灰置尾', muted: true },
]
for (const [nm, c] of Object.entries(TC.DOC_SEGMENTS || {})) {
  const seg = DOC_SEGMENTS.find((s) => s.name === nm)
  if (seg) seg.color = c
  else console.warn(`[gen] ⚠ themeColors.DOC_SEGMENTS 未知段名「${nm}」,忽略;合法:${DOC_SEGMENTS.map((s) => s.name).join(' / ')}`)
}
const SEG_BY_NAME = Object.fromEntries(DOC_SEGMENTS.map((s) => [s.name, s]))
// 缺省映射(照 demo B 注释;7 个法定 category 全覆盖);config.docSegments[cat] 逐类覆盖
const DOC_SEG_DEFAULT = {
  设计与决策: '地基',
  评审与审计: '流程', 计划与预案: '流程', 交接与接手: '流程',
  环境与指南: '操作',
  会话日志: '存档', 其他: '存档',
}
const segWarned = new Set()
function segKeyOfCat(cat) {
  const name = (cfg.docSegments && cfg.docSegments[cat]) || DOC_SEG_DEFAULT[cat]
  const seg = name && SEG_BY_NAME[name]
  if (!seg) {
    if (!segWarned.has(cat)) { console.warn(`[gen] ⚠ docSegments 未映射 category「${cat}」→ 落「存档」`); segWarned.add(cat) }
    return 'arc'
  }
  return seg.key
}

// ———— 决策路径入文档库(v0.15.0,config.pathTab:"docs")————
// 「决策路径」是给接手人一次性读完的来龙去脉,不是天天要点开的 tab。配成 "docs" 后:顶栏那一项与 pane 都不渲染,
// 同一份 path-manifest.json 改渲成 refs/design-path.html 一篇文档,登记进文档库 Hub(类别默认「交接与接手」,
// config.pathDocCategory 可改);#path 深链改落到文档库那条目 —— 数据一条不删,历史链接不死。
// 未配 = 一切照旧,产物逐字节冻结。
const PATH_DOCS = cfg.pathTab === 'docs'
if (cfg.pathTab !== undefined && !PATH_DOCS)
  console.warn(`[gen] ⚠ 未知 pathTab=${JSON.stringify(cfg.pathTab)},按未配处理(唯一合法值:"docs")`)
const PATH_DOC_OUT = 'design-path.html'
const PATH_DOC_TITLE = '设计路径(A→B→C)'
const PATH_DOC_SRC = `${KANBAN_REL}/path-manifest.json` // repo-root 相对(更新日期与 srcLabel 共用)
const PATH_DOC_CAT = (() => {
  const c = cfg.pathDocCategory
  if (c === undefined) return '交接与接手'
  if (DOC_CATS.includes(c)) return c
  console.warn(`[gen] ⚠ pathDocCategory「${c}」非法,退回「交接与接手」;合法值:${DOC_CATS.join(' / ')}`)
  return '交接与接手'
})()

// ———— 总览落地页(v0.15.0,config.overviewTab:true)————
// 第一个 pane(id 仍是 progress、hash 仍是 #)改渲一条叙事流:当前迭代 → 在验收 → 可做 → 待收账 →
// 沉睡 → 近 7 天 → 发布,原来的迭代任务表整块折进页底「迭代史」(深链照旧可达)。
// 每一行都从现有 manifest 与卡文件派生,零新数据源;数据源缺席的行整行不渲染。未配 = 逐字节冻结。
const OVERVIEW = cfg.overviewTab === true
const OV_RECENT_MAX = 20 // 「近 7 天动过的卡」最多列几张(超出只报个数)
const OV_RECENT_DAYS = 7

// 文档更新时间(真源 = git log 最后提交日;untracked/无 git 退回文件 mtime;都拿不到则空)—— gen 期取好嵌入。
// 一条 git log 批量取全部文档的最后提交日,不是一篇一条命令 —— 与 v0.14.0 的每卡更新日期同一招。
// 一个进程 fork 一次约 34ms,而守卫每次收工都跑 gen:55 篇文档就是 1.9s 的纯等待,还随文档数线性长。
const DOC_COMMITTED = new Map() // repo-root 相对路径 → 'YYYY-MM-DD'
{
  const paths = [...new Set((cfg.docs || []).map((d) => d && d.path).filter((x) => typeof x === 'string' && x)
    .concat(pm && PATH_DOCS ? [PATH_DOC_SRC] : []))] // 决策路径文档的更新日期走同一条批量 git log
  if (paths.length) {
    try {
      const out = execFileSync('git', ['log', '--format=%ad', '--date=short', '--name-only', '--', ...paths],
        { cwd: REPO_ROOT, stdio: ['ignore', 'pipe', 'ignore'], maxBuffer: 64 * 1024 * 1024 }).toString()
      let day = ''
      for (const raw of out.split('\n')) {
        const line = raw.trim()
        if (!line) continue
        if (/^\d{4}-\d{2}-\d{2}$/.test(line)) { day = line; continue }
        if (day && !DOC_COMMITTED.has(line)) DOC_COMMITTED.set(line, day) // git log 是新→旧,第一次见到即最后一次改动
      }
    } catch { /* 无 git / 命令失败 → 整批退 mtime */ }
  }
}
function docUpdated(relPath) {
  const day = DOC_COMMITTED.get(relPath)
  if (day) return day
  try { return statSync(join(REPO_ROOT, relPath)).mtime.toISOString().slice(0, 10) } catch { return '' }
}

const REF_DOCS = (cfg.docs || []).map((d, i) => {
  const where = `kanban.config.json docs[${i}](${d.path || d.out || '?'})`
  for (const k of ['path', 'out', 'title']) if (!d[k]) throw new Error(GS.docMissing(where, k))
  // out 直接拼进 REFS_DIR(html 复制 + md 渲染两侧共用),须是纯文件名 —— 含路径分隔符/.. 可写出 refs/ 外
  if (/[/\\]/.test(d.out) || d.out === '.' || d.out === '..') throw new Error(GS.docOutNotBasename(where, JSON.stringify(d.out)))
  if (d.type !== undefined && d.type !== 'html') throw new Error(GS.docUnknownType(where, JSON.stringify(d.type)))
  if (d.type === 'html') {
    // 自包含 HTML 指南(v0.4.0):gen 只复制不渲染;源可能在活 serve,须存在且是完整页面
    let raw = null
    try { raw = readFileSync(join(REPO_ROOT, d.path), 'utf8') } catch {}
    if (raw === null) throw new Error(GS.docHtmlUnreadable(where, d.path))
    if (!/<html/i.test(raw)) throw new Error(GS.docHtmlNotPage(where))
    if (Buffer.byteLength(raw) > 2 * 1024 * 1024) console.warn(`[gen] ⚠ ${where} 超 2MB,每次重生成整份复制进 refs/,考虑瘦身或只留 liveUrl 链出`)
  } else if (d.baseDir === undefined || d.baseDir === null) throw new Error(GS.docMissingBaseDir(where))
  if (!DOC_CATS.includes(d.category)) throw new Error(GS.docBadCategory(where, JSON.stringify(d.category), DOC_CATS.join(' / ')))
  return {
    src: d.path, out: d.out, title: d.title, baseDir: d.baseDir, cat: d.category, line: d.line || undefined,
    desc: d.desc || '', // 一句话定位(可选,缺省不渲染该行)
    order: Number.isFinite(d.order) ? d.order : null, // 阅读动线序号(可选)
    type: d.type, liveUrl: d.liveUrl || undefined, // type:"html" = 原样复制;liveUrl = 活实例地址(卡上「live ↗」徽标)
    seg: segKeyOfCat(d.category), updated: docUpdated(d.path),
  }
})
// 决策路径文档(pathTab:"docs"):不是 config.docs 里的条目,但从这里起与其它文档同一条命 ——
// 进 Hub、进 tab 计数、进 refs/,只有渲染那一步走 type:"path" 分支(源是 manifest 不是 markdown)。
if (pm && PATH_DOCS) {
  const taken = REF_DOCS.find((d) => d.out === PATH_DOC_OUT)
  if (taken) throw new Error(GS.pathDocOutTaken(PATH_DOC_OUT, taken.src))
  REF_DOCS.push({
    src: PATH_DOC_SRC, out: PATH_DOC_OUT, title: PATH_DOC_TITLE, baseDir: KANBAN_REL, cat: PATH_DOC_CAT,
    line: undefined, desc: '三纪元叙事:每一步为什么这么拐 —— 接手的人读一遍,不用天天读',
    order: null, type: 'path', liveUrl: undefined,
    seg: segKeyOfCat(PATH_DOC_CAT), updated: docUpdated(PATH_DOC_SRC),
  })
}
// out 同名冲突:HTML 复制件与 md 渲染件(或另一复制件)同名会在 refs/ 互相覆盖,牵涉即报错
{
  const byOut = new Map()
  for (const d of REF_DOCS) {
    const prev = byOut.get(d.out)
    if (prev && (prev.type === 'html' || d.type === 'html'))
      throw new Error(GS.docOutConflict(d.out, prev.src, d.src))
    if (!prev) byOut.set(d.out, d)
  }
}
const RENDERED = {} // repo-root 相对路径 → refs basename
for (const d of REF_DOCS) RENDERED[d.src] = d.out

// ---- 校验 ----------------------------------------------------------------
const iterIds = new Set(m.iterations.map((i) => i.id))
for (const t of m.tasks) {
  if (!iterIds.has(t.iteration)) throw new Error(GS.taskUnknownIteration(t.id, t.iteration))
  if (!(t.status in m.statuses)) throw new Error(GS.taskUnknownStatus(t.id, t.status))
}
const blGroupIds = new Set(b.groups.map((g) => g.id))
for (const it of b.items) {
  if (!(it.status in b.statuses)) throw new Error(GS.blUnknownStatus(it.id, it.status))
  if (!blGroupIds.has(it.status)) throw new Error(GS.blStatusNotInGroups(it.id, it.status))
  if (!(String(it.tier) in b.tiers)) throw new Error(GS.blUnknownTier(it.id, it.tier))
  if (!(it.priority in b.priorities)) throw new Error(GS.blUnknownPriority(it.id, it.priority))
}
const decGroupIds = new Set(dm.groups.map((g) => g.id))
for (const e of dm.entries) {
  if (!(e.status in dm.statuses)) throw new Error(GS.decUnknownStatus(e.id, e.status))
  if (e.closedKind && !['dropped', 'archived'].includes(e.closedKind)) throw new Error(GS.decUnknownClosedKind(e.id, e.closedKind))
  if (e.closedKind && e.status !== 'closed') throw new Error(GS.decClosedKindNeedsClosed(e.id))
  if (!decGroupIds.has(e.status)) throw new Error(GS.decStatusNotInGroups(e.id, e.status))
}

// ———— 项目换装(v0.4.0):看板目录 theme.css → 原样内联为每页 head 末位 <style>;缺席则零注入 ————
// 字面量→语义令牌走「条件间接层」:未启用 theme.css 时令牌按冻结原字面量直出(存量安装逐字节不变),
// 启用后同一处出 var(--令牌),:root 缺省 = 原字面量 —— 主题只覆盖变量,不必重写规则。
const THEME_CSS_FILE = join(HERE, 'theme.css')
let THEME_CSS = null
if (existsSync(THEME_CSS_FILE)) {
  if (!statSync(THEME_CSS_FILE).isFile()) throw new Error(GS.themeNotFile())
  THEME_CSS = readFileSync(THEME_CSS_FILE, 'utf8')
}
// </style> 逃逸守卫:HTML 关闭标签大小写不敏感、且 </style 后接空白/斜杠亦闭合,故大小写不敏感 + 覆盖 [\s/>] 变体
if (THEME_CSS !== null && /<\/style[\s/>]/i.test(THEME_CSS)) throw new Error(GS.themeHasCloseTag())
// 空 theme.css(0 字节/纯空白)= 视同未换装:注入空 <style> 会改字节、违背「无 theme.css 即逐字节冻结」承诺
if (THEME_CSS !== null && THEME_CSS.trim() === '') { console.warn('[gen] ⚠ theme.css 为空,按未换装处理'); THEME_CSS = null }
const THEMED = THEME_CSS !== null
const THEME_STYLE = THEMED ? `\n<style>${THEME_CSS}</style>` : '' // 三处 head:index / refs 页 / shots.html
// 主看板语义令牌(键名即 CSS 变量名;带注释的清单见 templates/theme.css.example)
const TOKENS = {
  /* 深色文字(深底主题必收敛,否则深底深字看不见) */
  'body-ink': '#44403c', 'sub-ink': '#57534e', 'note-ink': '#6b5d3e', 'sec-ink': '#1f5066',
  'ok-ink': '#047857', 'ok-ink-deep': '#065f46', 'warn-ink': '#b45309', 'gold-ink': '#9a6410',
  /* color-mix 烤入基色(badge/bbadge/rtag/stchip 共用,一处改盖一大片) */
  'mix-ink': '#2b2723', 'mix-paper': '#fff', 'tag-neutral': '#999',
  /* 浅色底(深底主题下的白块源) */
  'chip-hover': '#efeeeb', 'seg-bg': '#eceae6', 'info-bg': '#eaf1fa', 'gold-bg': '#fbf3e4',
  'warn-bg': '#fffbeb', 'sec-bg': '#e8f0f4', 'ref-bg': '#f1ebfb', 'ok-bg': '#d1f0e6',
  'ok-bg-faint': '#f0faf8', 'faint-bg': '#fafaf8', 'paper-tint': '#fbfaf7', 'brand-tint': '#f5fbfa',
  /* teal 品牌字面的带 alpha 变体(纯 teal 处直接走 var(--brand)) */
  'flag-glow': '#0f7b6c20', 'flash-glow': '#0f7b6c66',
}
const tk = (n) => {
  if (!(n in TOKENS)) throw new Error(GS.unknownToken(n))
  return THEMED ? `var(--${n})` : TOKENS[n]
}
const BRAND_TK = THEMED ? 'var(--brand)' : '#0f7b6c' // teal 品牌字面 → :root 既有 --brand
const CARD_TK = THEMED ? 'var(--card)' : '#fff' // 纯白面(lseg 滑块/obadge/pnode-planned)→ :root 既有 --card
const SHADOW_INK = THEMED ? 'var(--shadow-ink)' : '40,38,34' // 卡片阴影 rgba 基(R,G,B 三元)
const FONT_UI = `-apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC",
               "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif`
const FONT_UI_TK = THEMED ? 'var(--font-ui)' : FONT_UI
const MAIN_THEME_VARS = THEMED
  ? '\n          ' + Object.entries(TOKENS).map(([k, v]) => `--${k}:${v};`).join(' ') +
    `\n          --shadow-ink:40,38,34; --font-ui:${FONT_UI};`
  : ''
// refs/shots 侧令牌(REF_VARS 命名族:--panel/--text/--border/--muted;同一 theme.css 两套 :root 都要覆盖)
const REF_TOKENS = { 'soft-bg': '#f1f0ed', 'zebra-bg': '#faf9f7', 'quote-bg': '#eff6fb', 'quote-ink': '#3a4150' }
const rtk = (n) => {
  if (!(n in REF_TOKENS)) throw new Error(GS.unknownRefToken(n))
  return THEMED ? `var(--${n})` : REF_TOKENS[n]
}
const REF_TEXT_RGB = THEMED ? 'var(--text-rgb)' : '55,53,47' // 墨色低透 overlay 的 rgba 基
const REF_ACCENT_RGB = THEMED ? 'var(--accent-rgb)' : '35,131,226'
const REF_THEME_VARS = THEMED
  ? '\n  --text-rgb:55,53,47; --accent-rgb:35,131,226;\n  ' + Object.entries(REF_TOKENS).map(([k, v]) => `--${k}:${v};`).join(' ')
  : ''

// 语义色(对齐 demo/app:teal=成功、blue=进行/accent、amber=警示、red=超标/阻塞、grey=中性、purple=单列)
const STATUS_COLOR = tcMerge('STATUS_COLOR', {
  planned: '#a8a29e', active: '#2383e2', testing: '#b7791f',
  done: '#0f7b6c', blocked: '#d44c47', separate: '#8268b0',
})
const BL_STATUS_COLOR = tcMerge('BL_STATUS_COLOR', { ready: '#0f7b6c', blocked: '#b7791f', design: '#2383e2', deferred: '#a8a29e', done: '#3f7d70' })
const PRI_COLOR = tcMerge('PRI_COLOR', { high: '#d44c47', med: '#b7791f', low: '#a8a29e' })
const TIER_COLOR = tcMerge('TIER_COLOR', { 1: '#0f7b6c', 2: '#8268b0', 3: '#2383e2' })
const DEC_STATUS_COLOR = tcMerge('DEC_STATUS_COLOR', { deciding: '#b7791f', mockup: '#a8a29e', decided: '#0f7b6c', live: '#159b88', closed: '#8a8781' })
const PRI_ORDER = { high: 0, med: 1, low: 2 }
const CODE_EXT = /\.(py|ts|tsx|js|mjs|json|sh|sql|toml|cfg|txt|yml|yaml)$/i

// ———— 明暗模式(v0.9.0,config.darkMode:布尔,默认关)————
// 关 = 一切暗色注入不发生,输出逐字节冻结。开 = 每个色值包成 CSS light-dark(浅,深),
// 由 :root 的 color-scheme(跟随系统)+ [data-theme] 手动钮切换;连逐卡内联 style="--c:…" 也随主题变。
// 深色值:少量已拍板 pastel 锚点 + HSL 变换兜底(浅面翻深 / 深字翻浅 / 中间彩色压成 pastel)。
// 要求现代浏览器(light-dark()/color-scheme,2024+);内部工具场景,足够。
const DARK = cfg.darkMode === true
const DK_OVERRIDE = {
  '#f6f5f2': '#242220', '#ffffff': '#2d2a26', '#fff': '#2d2a26',
  '#37352f': '#e6e2da', '#6f6e6b': '#a29d92', '#8a8884': '#87837b',
  '#0f7b6c': '#8bc0b1', '#159b88': '#93c9ba', '#2383e2': '#95b5da',
  '#b7791f': '#d6b98d', '#d44c47': '#d9a69d', '#8268b0': '#b7a9d1',
  '#a8a29e': '#9b968c', '#8a8781': '#979288', '#e3e2e0': '#3a362f', '#ededec': '#33302b',
  // 角色已知的深「ink」(浅底深字 → 深底浅字)
  '#1f5066': '#a9cbdd', '#047857': '#6cc6a6', '#065f46': '#5fbd9c', '#b45309': '#e0b482',
  '#9a6410': '#d8bb8a', '#6b5d3e': '#ccbd97', '#44403c': '#d8d3c9', '#57534e': '#c6c1b7',
  '#2b2723': '#dcd7cd', '#78716c': '#a8a29a',
  // 角色已知的深/中彩色「accent」(→ pastel,不能翻成浅字)
  '#146152': '#8bc0b1', '#3f7d70': '#8bc0b1', '#1a6fc4': '#7ba0cf', '#d97706': '#dcb488',
  '#b5843a': '#d6b98d', '#7c3aed': '#b79bd6', '#7c2d12': '#d6a488',
  // 代码块本就深,保留
  '#0f172a': '#0f172a', '#e2e8f0': '#e2e8f0',
}
const dkHexToRgb = (h) => { h = h.replace('#', ''); if (h.length === 3) h = h.split('').map((c) => c + c).join(''); return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)] }
const dkRgbToHsl = (r, g, b) => {
  r /= 255; g /= 255; b /= 255
  const mx = Math.max(r, g, b), mn = Math.min(r, g, b); const l = (mx + mn) / 2; const d = mx - mn
  let h = 0, s = 0
  if (d) { s = l > 0.5 ? d / (2 - mx - mn) : d / (mx + mn); h = (mx === r ? (g - b) / d + (g < b ? 6 : 0) : mx === g ? (b - r) / d + 2 : (r - g) / d + 4) * 60 }
  return [h, s, l]
}
const dkHslToHex = (h, s, l) => {
  h = ((h % 360) + 360) % 360
  const c = (1 - Math.abs(2 * l - 1)) * s, x = c * (1 - Math.abs(((h / 60) % 2) - 1)), m = l - c / 2
  let r, g, b
  if (h < 60) [r, g, b] = [c, x, 0]; else if (h < 120) [r, g, b] = [x, c, 0]; else if (h < 180) [r, g, b] = [0, c, x]
  else if (h < 240) [r, g, b] = [0, x, c]; else if (h < 300) [r, g, b] = [x, 0, c]; else [r, g, b] = [c, 0, x]
  const to = (v) => Math.round((v + m) * 255).toString(16).padStart(2, '0')
  return '#' + to(r) + to(g) + to(b)
}
const darkOf = (hex) => {
  const raw = String(hex).toLowerCase()
  const m8 = raw.match(/^#([0-9a-f]{6})([0-9a-f]{2})$/) // 8 位带 alpha:变主色接回 alpha
  if (m8) return darkOf('#' + m8[1]) + m8[2]
  if (DK_OVERRIDE[raw]) return DK_OVERRIDE[raw]
  if (!/^#([0-9a-f]{3}|[0-9a-f]{6})$/.test(raw)) return raw
  const [h, s, l] = dkRgbToHsl(...dkHexToRgb(raw))
  let nl, ns
  if (s < 0.16) { // 中性:纯按亮度翻转,角色不明的中灰稳成中灰(两底都可见)
    if (l >= 0.72) { nl = 0.13 + (1 - l) * 0.85; ns = s }
    else if (l <= 0.42) { nl = 0.84 - l * 0.34; ns = s }
    else { nl = 0.54; ns = Math.min(s, 0.05) }
  } else if (l >= 0.82) { nl = 0.12 + (1 - l) * 0.9; ns = Math.min(s, 0.22) } // 彩色浅底/tint → 深
  else if (l <= 0.30) { nl = 0.64; ns = Math.min(s * 0.7, 0.4) } // 彩色很深 → pastel
  else { nl = 0.62 + (l - 0.34) * 0.26; ns = Math.min(s * 0.6, 0.42) } // 彩色中间 → pastel
  return dkHslToHex(h, ns, nl)
}
// darkStyle:把一段 CSS 里的色值全包成 light-dark();color:#fff 特殊(白字在 pastel 底上要变深墨)。
const DK_HEXRE = /#[0-9a-fA-F]{8}\b|#[0-9a-fA-F]{6}\b|#[0-9a-fA-F]{3}\b/g
const darkStyle = (css) => css
  .replace(/color:(\s*)#fff\b(?![0-9a-f])/gi, 'color:$1@@DKWT@@')
  .replace(DK_HEXRE, (m) => `light-dark(${m},${darkOf(m)})`)
  .replace(/@@DKWT@@/g, 'light-dark(#fff,#2a2620)')
// darkenDoc:只在 <style> 块内做色值替换,不碰 body / script;关时原样返回。
const darkenDoc = (docHtml) => !DARK ? docHtml : docHtml.replace(/<style>([\s\S]*?)<\/style>/g, (_, css) => `<style>${darkStyle(css)}</style>`)

const esc = (s) =>
  String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
// 色值注入 style 属性专用:先 String() 再 esc —— 堵 config 色值的引号逃逸,同时把未知色键(如 TIER_COLOR[未定义 tier])
// 的 undefined 保留成字面 "undefined"(esc 的 ?? '' 会吞成空串,改字节),与 v0.5.0 逐字节一致。
const escC = (c) => {
  const s = esc(String(c))
  return DARK && /^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$/.test(String(c)) ? `light-dark(${s},${darkOf(String(c))})` : s
}

// ———— session 权责标签(v0.5.0):机制归 plugin、数据归项目 ————
// config.sessionTags(可选、保插入序):{ id: { label, desc, color? } };color 缺省从安静内置轮换板取。
// 卡片条目(decisions/backlog)可选 session 字段 = 空格分隔 id(可多标,沿文档库 line "B C" 先例)。
// 【字节冻结】空对象/缺席 = 视同不存在:全部 session 产物走 '' 分支,输出与 v0.4.0 逐字节一致。
const SESSION_PALETTE = ['#5b7fb0', '#a8814e', '#5a9b83', '#8f77ab', '#b56f6f', '#5f8f9e', '#9a8b52', '#7a8a70']
const ST_RAW = (cfg.sessionTags && typeof cfg.sessionTags === 'object' && !Array.isArray(cfg.sessionTags)) ? cfg.sessionTags : {}
const SESSION_IDS = Object.keys(ST_RAW)
const SESSION_ON = SESSION_IDS.length > 0
const SESSION_TAGS = {}
SESSION_IDS.forEach((id, i) => {
  const t = ST_RAW[id] || {}
  SESSION_TAGS[id] = { label: t.label || id, desc: t.desc || '', color: t.color || SESSION_PALETTE[i % SESSION_PALETTE.length] }
})
const sessIdsOf = (entry) => String(entry.session || '').split(/\s+/).filter(Boolean)
const sessWarned = new Set()
// 卡片 data-session 属性(空格分隔 id;off 或无标 → '' = 字节冻结)
const sessAttr = (entry) => {
  if (!SESSION_ON) return ''
  const ids = sessIdsOf(entry)
  return ids.length ? ` data-session="${esc(ids.join(' '))}"` : ''
}
// 卡上小章(安静低饱和,贴 rtag chip 习语);未定义 id → 警告 + 灰章,不崩;label 过 esc 防注入
const sessSeals = (entry) => {
  if (!SESSION_ON) return ''
  return sessIdsOf(entry).map((id) => {
    const t = SESSION_TAGS[id]
    if (!t) {
      if (!sessWarned.has(id)) { console.warn(`[gen] ⚠ 卡片 ${entry.id} 的 session 标签「${id}」未在 config.sessionTags 定义 —— 按灰章渲染`); sessWarned.add(id) }
      return `<span class="cardsess unknown" title="未定义的 session 标签:${esc(id)}">${esc(id)}</span>`
    }
    return `<span class="cardsess" style="--sc:${esc(t.color)}" title="${esc(t.desc || t.label)}">${esc(t.label)}</span>`
  }).join('')
}

// ———— 线别(lanes):config 驱动,可选。null / 缺省 = 关(新项目默认)。 ————
// 开 = config.lanes 给对象 { ids:[…], default?, titles?, typeLabels?, hints?, hubSuffix?, blSess? };
// 线别归属读每条 entry 的显式 line 字段(decisions / backlog / tasks / iterations / docs 均可标,
// 空格分隔可多线共享,如 "B C")。hints/blSess 值按可信 HTML 原样注入(与其它 config 文案同级)。
// 兼容:字符串 "lamos-legacy" 作已弃用别名(= 最小 A/B/C 默认),将在下一版移除。
let LANES // null(关)或规整后的对象
{
  const raw = cfg.lanes ?? null
  if (raw === null) LANES = null
  else if (raw === 'lamos-legacy') {
    console.warn('[gen] ⚠ config.lanes 的字符串形式已弃用,请改为对象形式(见 kanban-init SKILL);本别名将在下一版移除')
    LANES = { ids: ['A', 'B', 'C'], default: 'C', titles: {}, typeLabels: {}, hints: {}, hubSuffix: '', blSess: '' }
  } else if (raw && typeof raw === 'object' && !Array.isArray(raw) && Array.isArray(raw.ids) && raw.ids.length) {
    LANES = {
      ids: raw.ids.map(String),
      default: raw.default != null ? String(raw.default) : String(raw.ids[0]),
      titles: raw.titles || {},
      typeLabels: raw.typeLabels || {},
      hints: raw.hints || {},
      hubSuffix: raw.hubSuffix != null ? String(raw.hubSuffix) : '',
      blSess: raw.blSess != null ? String(raw.blSess) : '',
    }
  } else throw new Error(GS.lanesInvalid(JSON.stringify(raw)))
}
// ———— 品牌参数化:线别 UI 里的品牌串随 config.brand 走 ————
const BRAND_H = esc(BRAND) // HTML 文本上下文
const BRAND_JS = BRAND.replace(/[\\']/g, '\\$&') // 生成 JS 里的单引号字符串字面量
const BRAND_RE = BRAND.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&') // 生成 JS 里的正则字面量
// localStorage 前缀:brand slug(换名重置一次偏好,拍板不迁移)
const LS_PREFIX = BRAND.toLowerCase().replace(/[^a-z0-9]+/g, '') || 'kanban'
// ———— 懒加载拆页(v0.11.0,config.lazyTabs:布尔,默认关)————
// 关 = 单文件,输出逐字节冻结。开 = 长内容的 pane 正文外提 parts/*.html(v0.11.0 决策/Backlog,
// 0.13.0 加归档,0.15.0 加验收与发布进度 —— 后三个各自的 tab 开着才有那一份;其余 pane 留壳内),
// 壳内放骨架卡,切 tab 即时切换、fetch 注入正文(真字节进度走顶部 2px 细线);注入后补课一条链
// (工具条接线 → 搜索补戳 → 时间筛补戳,全幂等)闭合跨 pane 契约;深链靠 gen 期烤入的
// 卡号→pane 映射先取再定位;搜索框一有输入即拉全未取 chunk,保住全局搜索/徽章计数口径。
// 看板只经 serve.py 访问(无 file:// 口径),fetch 无兼容包袱。
const LAZY = cfg.lazyTabs === true
const LAZY_CSS = !LAZY ? '' : `
  #lazybar { position: fixed; top: 0; left: 0; height: 2px; background: var(--brand); width: 0; z-index: 70; opacity: 0; transition: width .12s linear, opacity .3s; }
  #lazybar.on { opacity: 1; }
  .lazyskel { padding-top: 6px; }
  .lazyskel .skel { border: 1px solid var(--line); border-left: 3px solid var(--line-strong); border-radius: 10px; padding: 12px 14px; margin-bottom: 10px; background: var(--card); }
  .lazyskel .sb { height: 10px; border-radius: 5px; background: linear-gradient(90deg, ${tk('seg-bg')} 25%, ${tk('faint-bg')} 45%, ${tk('seg-bg')} 65%); background-size: 200% 100%; animation: lazyshim 1.2s linear infinite; }
  .lazyskel .sb.w1 { width: 64px; }
  .lazyskel .sb.w2 { width: 72%; height: 12px; margin-top: 8px; }
  .lazyskel .sb.w3 { width: 34%; margin-top: 9px; }
  @keyframes lazyshim { from { background-position: 200% 0 } to { background-position: -200% 0 } }
  @media (prefers-reduced-motion: reduce) { .lazyskel .sb { animation: none } }
  .lazyerr { color: var(--mut); font-size: 13px; padding: 34px 0; text-align: center; }
  .lazyerr button { font: inherit; font-size: 12.5px; color: var(--accent); background: var(--card); border: 1px solid var(--line-strong); border-radius: 7px; padding: 3px 12px; cursor: pointer; margin-left: 6px; }`
const LAZY_SKEL = !LAZY ? '' : `\n  <div class="lazyskel">${`\n    <div class="skel"><div class="sb w1"></div><div class="sb w2"></div><div class="sb w3"></div></div>`.repeat(4)}\n  </div>\n  `
const LAZY_BAR = !LAZY ? '' : `\n<div id="lazybar"></div>`
// ———— 明暗模式的门控注入片(DARK 关时全为 '',逐字节冻结)————
// color-scheme 令 light-dark() 生效:基态跟随系统,[data-theme] 手动覆盖(手选压过系统)。
const DK_SCHEME_CSS = !DARK ? '' : `
  :root { color-scheme: light dark; }
  :root[data-theme="dark"] { color-scheme: dark; }
  :root[data-theme="light"] { color-scheme: light; }
  .themetoggle { appearance: none; cursor: pointer; font: inherit; font-size: 14px; line-height: 1; padding: 5px 9px;
    border: 1px solid; border-color: color-mix(in srgb, currentColor 24%, transparent); border-radius: 8px;
    background: transparent; color: inherit; opacity: .8; }
  .themetoggle:hover { opacity: 1; border-color: color-mix(in srgb, currentColor 42%, transparent); }
  .themetoggle:focus-visible { outline: 2px solid var(--accent, #2383e2); outline-offset: 2px; }`
// 切换钮(跟随系统 + 手动切;同一 LS key,index/refs/shots 偏好互通)。空 title 走 aria-label。
// 防主题闪错(FOUC):手选主题的恢复必须在首帧之前——三行同步脚本前置 <head>、样式之前,
// 否则大文件/弱链路下「按系统渲染几秒 → 末尾脚本才拨回手选」肉眼可见(宿主 app 侧 BL-C49 同款打法)。
const DK_BOOT = !DARK ? '' : `
<script>try { var t = localStorage.getItem('${LS_PREFIX}_theme'); if (t === 'dark' || t === 'light') document.documentElement.setAttribute('data-theme', t) } catch (e) {}</script>`
const DK_TOGGLE_BTN = !DARK ? '' : `<button type="button" id="themetoggle" class="themetoggle" aria-label="切换明亮 / 暗夜" title="明亮 / 暗夜(跟随系统,可手动切)">☾</button>`
const DK_TOGGLE_JS = !DARK ? '' : `
  ;(function () {  // 前置分号:本码库无分号风格(ASI),紧跟在 routeHash() 后会被解析成 routeHash()(…),必须挡开
    var KEY = '${LS_PREFIX}_theme', root = document.documentElement, btn = document.getElementById('themetoggle')
    var mq = window.matchMedia && matchMedia('(prefers-color-scheme: dark)')
    function eff() { var c = root.getAttribute('data-theme'); return c ? c : (mq && mq.matches ? 'dark' : 'light') }
    function paint() { if (btn) btn.textContent = eff() === 'dark' ? '☀' : '☾' }
    try { var s = localStorage.getItem(KEY); if (s === 'dark' || s === 'light') root.setAttribute('data-theme', s) } catch (e) {}
    paint()
    if (mq && mq.addEventListener) mq.addEventListener('change', paint)
    if (btn) btn.addEventListener('click', function () {
      var n = eff() === 'dark' ? 'light' : 'dark'
      root.setAttribute('data-theme', n)
      try { localStorage.setItem(KEY, n) } catch (e) {}
      paint()
    })
  })();`
const LANES_ON = LANES !== null // 线别 UI(工具条分段/文档库 chips/hint/h1 重写)只在此开
const LANE_IDS = LANES_ON ? LANES.ids : []
// 决策路径那篇是 A→B→C 全叙事(与那个 pane 同一句话:不随线路筛选收敛)—— 每一档都算它的,
// 否则筛到任一档它就从文档库消失,#path 深链会滚到一张 display:none 的卡上。
// (线别规整在这一行才完成,所以这个字段在 REF_DOCS 建好之后补,不在建的时候写。)
if (LANES_ON && PATH_DOCS) { const d = REF_DOCS.find((x) => x.type === 'path'); if (d) d.line = LANE_IDS.join(' ') }
// 线别归属:开时读每条 entry 的显式 line 字段(通用、可审计);关时恒空 —— 产物与未开线别逐字节一致。
const lineOf = (e) => LANES_ON ? String((e && e.line) || '') : ''
const decLine = lineOf, iterLine = lineOf, docLine = lineOf, taskLine = lineOf, blLine = lineOf
// 线别开时的每档 hint 区块:按 ids 序渲染有 hint 的档;值按可信 HTML 原样注入(id 过 esc)
const laneHintsHtml = LANES && Object.keys(LANES.hints).length
  ? `\n  <div class="linehints">${LANES.ids.map((id) => LANES.hints[id] ? `\n    <span class="lf-hint" data-line-note="${esc(id)}">${LANES.hints[id]}</span>` : '').join('')}\n  </div>`
  : ''
const LANE = LANES_ON ? {
  hubbrand: LANES.hubSuffix ? `${BRAND_H}${esc(LANES.hubSuffix)}` : BRAND_H,
  defaultLine: LANES.default,
  lsLineKey: `${LS_PREFIX}_hub_line`,
  lsTfKey: `${LS_PREFIX}_hub_tf`,
  lineTitles: LANES.titles,
  typeLabels: LANES.typeLabels,
  lineHintsHtml: laneHintsHtml,
  h1RewriteJs: `
    // 顶栏 h1 随档换前缀:${BRAND}-<默认档> / ${BRAND} → ${BRAND}(-X)
    document.querySelectorAll('.pane .topbar h1').forEach(function (h) {
      if (h.dataset.base === undefined) h.dataset.base = h.textContent
      const pre = line === 'all' ? '${BRAND_JS}' : '${BRAND_JS}-' + line
      h.textContent = h.dataset.base.replace(/^${BRAND_RE}(-${LANES.default})?/, pre)
    })`,
  savedLineJs: `  let savedLine = '${LANES.default}'
  try { savedLine = localStorage.getItem('${LS_PREFIX}_hub_line') || '${LANES.default}' } catch (e) {}`,
  blSessHtml: LANES.blSess ? `\n    <span class="sess">${esc(LANES.blSess)}</span>` : '',
  blStamp: '由 <code>gen.mjs</code> 生成自 <code>backlog-manifest.json</code> — 改完重跑生成。',
  decStamp: '由 <code>gen.mjs</code> 生成自 <code>decisions-manifest.json</code> — demo 存 <code>kanban/demos/</code>。',
} : {
  hubbrand: esc(BRAND),
  defaultLine: 'all',
  lsLineKey: `${LS_PREFIX}_hub_line`,
  lsTfKey: `${LS_PREFIX}_hub_tf`,
  lineTitles: {},
  typeLabels: {},
  lineHintsHtml: '',
  h1RewriteJs: '',
  savedLineJs: `  let savedLine = 'all'`,
  blSessHtml: '',
  blStamp: '由 <code>gen.mjs</code> 生成自 <code>backlog-manifest.json</code> — 改完重跑生成。',
  decStamp: '由 <code>gen.mjs</code> 生成自 <code>decisions-manifest.json</code> — demo 存 <code>kanban/demos/</code>。',
}

// 长文折叠(信息密度):运行期在 pane 可见时量高打 .clamp(字符数近似会被列宽骗——
// 三列栅格下 96 字 ≈5 行;display:none 面板量高为 0,故只量可见元素,见内联 clampScan)

const ghCommit = (hash) => `https://github.com/${m.instance.ghRepo}/commit/${hash}`

// baseDir(repo-root 相对)+ href → 规范化 repo-root 相对路径(POSIX)。
function resolveRepoPath(baseDir, href) {
  const parts = (baseDir ? baseDir.split('/') : []).concat(href.split('/'))
  const stack = []
  for (const p of parts) {
    if (p === '' || p === '.') continue
    if (p === '..') stack.pop()
    else stack.push(p)
  }
  return stack.join('/')
}

// ———— href 的 scheme 白名单 ————
// manifest 与卡里的链接是仓库里的数据,但「仓库里的数据」不等于「可以当代码执行」:
// javascript: 的链接一点就在看板自己的源上跑脚本,而验收清单的勾选状态全存在这个源的
// localStorage 里。esc() 挡得住属性逃逸,挡不住 scheme —— 这里挡。
// 相对路径不带 scheme(refs/… 、demos/… 、#锚点),一律原样放行。
const HREF_SCHEME = /^[a-z][a-z0-9+.-]*:/i
const HREF_ALLOW = /^(?:https?|mailto):/i
const hrefWarned = new Set()
function safeHref(href) {
  const raw = String(href ?? '')
  if (!HREF_SCHEME.test(raw) || HREF_ALLOW.test(raw)) return raw
  if (!hrefWarned.has(raw)) {
    hrefWarned.add(raw)
    console.warn(`[gen] ⚠ 链接 ${JSON.stringify(raw.slice(0, 80))} 的协议不在白名单(http / https / mailto),已渲染成不可点 —— 改掉它或写成相对路径`)
  }
  return '#'
}

// 卡片 link(相对 kanban/)→ 渲染页 / GitHub blob / 原样。
function cardLink(href) {
  const raw = String(href || '')
  if (/^https?:/i.test(raw)) return { href: raw, ext: true }
  let frag = '', path = raw
  const hi = raw.indexOf('#')
  if (hi >= 0) { frag = raw.slice(hi); path = raw.slice(0, hi) }
  const repoPath = resolveRepoPath(KANBAN_REL, path)
  if (RENDERED[repoPath]) return { href: 'refs/' + RENDERED[repoPath] + frag }
  if (CODE_EXT.test(repoPath)) return { href: GH_BLOB + repoPath + frag, ext: true }
  return { href: safeHref(raw) }
}
const linkA = (l) => {
  const r = cardLink(l.href)
  const rs = respLinkParts(l) // v0.13.0:本仓 PR 链接补真实状态(无 release-manifest 时恒 null,零差异)
  return `<a href="${esc(r.href)}"${r.ext ? ' target="_blank" rel="noopener"' : ''}>↗ ${rs ? rs.title : esc(l.title)}${rs ? rs.suffix : ''}</a>`
}

// ============================================================================
//  PR 关联 + 验收清单(v0.12.0)
//  卡上可选 `pr` 字段 → 卡头芯片;acceptance-manifest.json(opt-in)→「验收」tab。
//  两者都缺席时,以下全部片段求值成空串 —— 输出对 0.11.4 逐字节冻结。
// ============================================================================
const PR_REPO = (m.instance && m.instance.ghRepo) || ''
const ALL_CARDS = [...m.tasks, ...b.items, ...dm.entries]
// 芯片只认显式 pr 字段;links 兼容(prsOfCard)只用于「PR ↔ 卡」反查 —— 否则存量看板的
// 旧 PR 链接会凭空长出芯片,冻结承诺当场破。
const HAS_PR = ALL_CARDS.some((c) => c && c.pr !== undefined && c.pr !== null)
const prUrl = (p) => `https://github.com/${p.repo}/pull/${p.num}`
const prLabel = (p) => (p.repo === PR_REPO ? `PR #${p.num}` : `${p.repo.split('/').pop()}#${p.num}`)

// ———— release-manifest.json(由 pr-sync 写,gen 只读)————
// releaseTab 开 → 必须在场且合法(硬报错);关 → 在场才读,只用来给 PR 芯片配状态后缀。
// 两者都缺席 = 后缀恒空,不读、不渲染,零差异。
const REL = cfg.releaseTab === true
const REL_PATH = join(HERE, 'release-manifest.json')
let rlm = null
if (REL) {
  try { rlm = JSON.parse(readFileSync(REL_PATH, 'utf8')) }
  catch (e) { throw new Error(GS.relManifestMissing(e.message)) }
} else if (existsSync(REL_PATH)) {
  try { rlm = JSON.parse(readFileSync(REL_PATH, 'utf8')) }
  catch (e) { console.warn(`[gen] ⚠ release-manifest.json 无法解析,PR 状态后缀不渲染:${e.message}`) }
}
// 段:语义固定,宿主只改 label/hint,可只列两段(缺 test = 合了即发);缺 dev 不允许。
const REL_STAGES = !REL ? [] : (rlm.stages || []).filter((s) => s && s.id != null).map((s) => ({ id: String(s.id), label: String(s.label ?? s.id), hint: String(s.hint ?? '') }))
const REL_STAGE_IDS = new Set(REL_STAGES.map((s) => s.id))
if (REL && !REL_STAGE_IDS.has('dev')) throw new Error(GS.relStagesNoDev())
const REL_MAIN = (m.instance && m.instance.branch) || '' // 主线分支:base 不是它的 PR 标「非主线」
const relPr = new Map() // PR 号 → pr 记录
if (rlm) for (const p of rlm.prs || []) if (p && p.number != null) relPr.set(Number(p.number), p)
// 归版规则(显式 releases[].prs 优先,否则 at ≥ mergedAt 的最早 release)住在 relstage.mjs,
// 芯片后缀与发布进度 tab 共用同一个 relTagFor —— 两处各写一遍就是两套口径。
// at 是打 tag 的精确时刻:归版、分组、排序全挂在它上面。缺了不阻断(显式 prs 仍认),但要出声。
if (rlm) for (const r of rlm.releases || []) if (r && r.tag && !r.at) {
  console.warn(`[gen] ⚠ release-manifest.json:版本 ${r.tag} 没写 at(打 tag 的精确时刻)—— 归版与分组全靠它,这一版只认显式写在 prs 里的 PR;补上 at,或跑一次 pr-sync.mjs`)
}
const REL_IDX = relIndex(rlm ? rlm.releases || [] : [])
const relSorted = REL_IDX.sorted
const relTagFor = REL_IDX.tagFor
const prStatus = (p) => {
  if (p.repo !== PR_REPO) return '' // 跨仓 PR 的状态不在本仓 manifest 里
  const r = relPr.get(p.num)
  if (!r) return ''
  // 非主线排在最前,与 relstage.mjs 的段判定同序:叠在别人分支上的 PR 合了也不代表进了主线,
  // 芯片说「已发 v0.0.3」而表格说「非主线」就是两套口径。
  // (不能直接调 stageOf:releaseTab 关着时 REL_STAGE_IDS 是空的,merged-未归版会被判成 prod。)
  if (REL_MAIN && r.base && r.base !== REL_MAIN) return '非主线'
  if (r.state === 'closed') return '已关闭'
  if (r.state === 'open') return r.draft ? '草稿' : '开着'
  if (r.state !== 'merged') return ''
  const tag = relTagFor(r)
  return tag ? `已发 ${tag}` : `已合 ${String(r.mergedAt || '').slice(5, 10)}`
}

// ———— 进度响应(v0.13.0,定稿 §2):PR 状态回流到卡片 ————
// 门控与芯片后缀同一条:release-manifest.json 在场才有判断依据,缺文件 = 本节全部空串、零差异。
// 「PR 合了」≠「卡可以收」——所以只出提示,不静默改 manifest(改写走 pr-sync --settle --write)。
const RESP = Boolean(rlm)
const RESP_DORM = 30 // 沉睡阈值(天);天数在浏览器算,gen 只烤日期
const respOf = (entry) => settleOf(entry, prsOfCard(entry, PR_REPO), relPr, PR_REPO)
// 卡头芯片:settle / reopen 各一枚;都不是但多 PR 部分合并 → 安静报个「2/3 已合」。
// 卡上写了 settleHold = 人已经看过这张卡并判定「这一轮不收」,机器不再重复它已经知道的事:
// 只留一枚灰芯片,理由挂 title(v0.13.1)。它换掉的是那三枚里的任意一枚,不是叠在它们上面。
const respChips = (entry) => {
  if (!RESP) return ''
  const hold = settleHold(entry)
  if (hold) return `<span class="rspchip rsp-hold" title="${esc(hold)}">暂不收账</span>`
  const s = respOf(entry)
  if (s.kind === 'settle') return '<span class="rspchip rsp-settle" title="所有关联 PR 都已合并,卡还没收到终态 —— 跑 pr-sync.mjs --settle 看清单">PR 已合 · 待收账</span>'
  if (s.kind === 'reopen') return '<span class="rspchip rsp-reopen" title="卡已在终态,但还有关联 PR 开着">已收账但 PR 未合</span>'
  if (s.total > 1 && s.merged > 0 && s.merged < s.total) return `<span class="rspchip rsp-part" title="这张卡跨了 ${s.total} 个 PR">${s.merged}/${s.total} 已合</span>`
  return ''
}
// 沉睡:ready + 有日期 + 一个 PR 都没挂。天数与阈值判定都在浏览器(gen 零时间),这里只烤日期。
// cardsDir 开着时天数从「卡文件最后改动日」起算 —— 比建卡 date 诚实(0.13.0 用 date 是当时没有更好的事实)。
const dormChip = (entry) => {
  if (!RESP) return ''
  const d = dormantDate(entry)
  return d && !prsOfCard(entry, PR_REPO).length
    ? `<span class="rspdorm" data-dorm="${esc((CARDS_DIR && cardUpd(entry.id)) || d)}" hidden></span>`
    : ''
}
// links 里指向本仓 /pull/N 的链接:补真实状态后缀;标题里手写的状态词若已过时,划掉(不改数据)。
// 复用 prsOfCard 认号 —— 与卡的 PR 集合同一条口径,不另写一遍 href 正则。
const respLinkParts = (l) => {
  if (!RESP) return null
  const p = prsOfCard({ links: [l] }, PR_REPO)[0]
  if (!p) return null
  const st = prStatus(p)
  if (!st) return null // 没同步过的号:不知道就不说
  const hit = staleLink(l, relPr, PR_REPO)
  const title = esc(String(l.title ?? ''))
  return {
    title: hit ? title.replace(hit.word, `<s class="stale">${hit.word}</s>`) : title,
    suffix: `<span class="prst">${esc(st)}</span>`,
  }
}

// ———— acceptance-manifest.json(config.acceptanceTab === true 才读;缺省即使文件在也不读)————
const ACC = cfg.acceptanceTab === true
let acm = null
if (ACC) {
  try { acm = JSON.parse(readFileSync(join(HERE, 'acceptance-manifest.json'), 'utf8')) }
  catch (e) { throw new Error(GS.accManifestMissing(e.message)) }
}
const accWarn = (msg) => console.warn(`[gen] ⚠ acceptance-manifest:${msg}`)
// 清单规整:pr 串(锚与 localStorage 键)、revision(改动即作废旧勾选)、分组/条目/数据块。
// 软校验一律 console.warn 不阻断 —— 清单是人写的正文,坏一条不该把整块板打死。
const ACC_LISTS = !ACC ? [] : (acm.lists || []).map((l) => {
  const nums = (Array.isArray(l.pr) ? l.pr : [l.pr]).map(Number).filter((n) => Number.isFinite(n) && n > 0)
  const groups = (l.groups || []).length ? l.groups : [{ id: '_', title: l.title || '清单', tip: '' }]
  const gids = new Set(groups.map((g) => String(g.id)))
  const rounds = l.rounds || []
  const rids = new Set(rounds.map((r) => String(r.id)))
  const data = l.data || {}
  const seen = new Set()
  const items = (l.items || []).map((it) => {
    const id = String(it.id ?? '')
    if (seen.has(id)) accWarn(`清单 ${nums.join('/')} 条目 id 重复:${id}`)
    seen.add(id)
    const g = String(it.group ?? groups[0].id)
    if (!gids.has(g)) accWarn(`清单 ${nums.join('/')} 条目 ${id} 的 group「${g}」不在 groups`)
    if (it.round && !rids.has(String(it.round))) accWarn(`清单 ${nums.join('/')} 条目 ${id} 的 round「${it.round}」不在 rounds`)
    for (const k of it.data || []) if (!data[k]) accWarn(`清单 ${nums.join('/')} 条目 ${id} 引用了不存在的数据块「${k}」`)
    return { ...it, id, group: gids.has(g) ? g : String(groups[0].id), pr: it.pr != null ? Number(it.pr) : nums[0], round: it.round ? String(it.round) : '' }
  })
  return { ...l, nums, key: nums.join('-'), rev: Number.isFinite(l.revision) ? l.revision : 1, env: l.env || {}, rounds, groups, items, data, cards: l.cards || [] }
})
{ // 同一 PR 出现在两份清单 = 勾选进度会分家,提醒
  const owner = new Map()
  for (const l of ACC_LISTS) for (const n of l.nums) {
    if (owner.has(n)) accWarn(`PR #${n} 同时出现在两份清单(${owner.get(n)} 与 ${l.key})`)
    else owner.set(n, l.key)
  }
}
const ACC_BY_PR = new Map()
for (const l of ACC_LISTS) for (const n of l.nums) if (!ACC_BY_PR.has(n)) ACC_BY_PR.set(n, l)
const ACC_CUR = ACC ? ACC_BY_PR.get(Number(acm.current)) || null : null
// 「验收中」是派生的,不加新状态枚举:current 那份,或(有 release-manifest 时)PR 还开着的那份
const accLive = (n) => Boolean(ACC_BY_PR.get(n)) && (Number(acm.current) === n || (relPr.get(n) || {}).state === 'open')

// 卡头芯片:PR + 状态后缀 +(验收开时)清单链与运行期进度。无 pr 字段 → '' = 逐字节冻结。
const prChips = (entry) => declaredPrs(entry, PR_REPO).map((p) => {
  const st = prStatus(p)
  const l = p.repo === PR_REPO ? ACC_BY_PR.get(p.num) : null
  return `<a class="prchip" href="${esc(prUrl(p))}" target="_blank" rel="noopener">${esc(prLabel(p))}${st ? `<span class="prst">${esc(st)}</span>` : ''}</a>` +
    (l ? `<a class="acclink" href="#acc-${p.num}">清单</a>` : '') +
    (l && accLive(p.num) ? `<span class="accnow">验收中 · <span data-acc="${p.num}">0/${l.items.length}</span></span>` : '')
}).join('')

// 清单正文:esc 之后只认 **粗体**,换行留成 <br>(照卡片 repro 的做法);数组按段落
const bold = (s) => Array.isArray(s)
  ? s.map((x) => bold(x)).join('<br>')
  : esc(String(s ?? '')).replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>').replace(/\n/g, '<br>')

// ———— 卡正文轻 markdown(v0.13.0,config.richText:布尔,默认关)————
// 关 = 三种卡的长文本字段照旧只 esc()、换行被 white-space 折叠,输出逐字节冻结。
// 开 = 走 lite.mjs:**粗体** / `代码` / 段落 / <br> / 列表 / ①…⑩ / 【…】小节(见 lite.mjs 头注)。
// 超 RICH_N 字的字段烤两份(预览 + 全文,按段落边界切),运行期点钮换 hidden —— 折叠不记忆;
// 没超的照旧交给 clampScan 按高度折(两套折叠不叠加,clampScan 见 .lfull 即让路)。
// detail 字段(查证细节)同受本开关门控:没开 richText 的板一律零差异。
const RICH = cfg.richText === true
const RICH_N = 400 // 预览段长(定稿 §6.1-2)
const NOTES_TAG = RICH ? 'div' : 'p' // <p> 里塞不进 <p>/<ul>(HTML 解析器会当场闭合 p,正文整段逃出容器)
// 一个长文本字段的正文;三种卡共用。关档时与 esc(x) 逐字节相同。
const rt = (text) => {
  const s = String(text ?? '')
  if (!RICH) return esc(s)
  const { head, rest } = litePreview(s, RICH_N)
  if (rest <= 0) return `<div class="lite">${lite(s)}</div>`
  return `<div class="lite lpre">${lite(head)}</div><div class="lite lfull" hidden>${lite(s)}</div><button type="button" class="litemore" data-rest="${rest}">展开 · 还有 ${rest} 字</button>`
}
// detail:摘要与细节分家(定稿 §3.3)——渲染在卡内所有字段之后,默认折叠。无字段零差异。
const detailBlock = (card) => {
  const s = String((card && card.detail) || '')
  return !RICH || !s ? '' : `
      <details class="detail"><summary>查证细节<span class="n"> · ${s.length} 字</span></summary><div class="dbody lite">${lite(s)}</div></details>`
}
// 决策卡的 source:0.12.0 前有数据没渲染(死数据)。补成与 backlog 同款小徽章,门控在 richText 下
// (否则存量板一开 gen 就多出一行,破冻结);正文走 lite,徽章 inline-block 才容得下段落。
const decSrcRow = (e) =>
  !RICH || !e.source ? '' : `<dt>来源</dt><dd class="lsrc"><span class="bbadge src">${lite(String(e.source))}</span></dd>
        `

// ---- demo 返回栏(幂等注入 demos/*.html 顶部;回看板「决策/Demo」tab)----
// 版本号 bump 时:旧版本块整块剥离后重注入,文案/样式跟着 gen 演进(否则幂等守卫会让旧文案永远留在已注入的 demo 里)
// 元素/marker 用中性 ddd-backnav,ctx 文案随 config.brand。
// ponytail: 返回栏不进换装范围——它注入进全体 demos/*.html,动样式会 churn 全部 demo 文件;
//           将来要主题化时走 BACKNAV_VER bump(旧块整块剥离重注入),色值对齐 index :root 令牌。
const BACKNAV_VER = 'ddd-backnav v3'
const BACKNAV_BLOCK = `<!-- ${BACKNAV_VER} -->
<style id="ddd-backnav-style">
 body{padding-top:44px}
 #ddd-backnav{position:fixed;top:0;left:0;right:0;height:44px;z-index:9999;display:flex;align-items:center;gap:10px;padding:0 16px;background:#f6f5f2;border-bottom:1px solid #e3e2e0;font:13px -apple-system,"PingFang SC","Microsoft YaHei",sans-serif}
 #ddd-backnav a{display:inline-flex;align-items:center;gap:6px;text-decoration:none;font-weight:600;color:#2383e2;border:1px solid #e3e2e0;border-radius:8px;padding:5px 11px;background:#fff}
 #ddd-backnav a:hover{border-color:#2383e2}
 #ddd-backnav .ctx{color:#6f6e6b;font-size:12px}
</style>
<nav id="ddd-backnav"><a href="../index.html#decisions">← 返回看板</a><span class="ctx">${esc(BRAND)} Demo · mock 数据</span></nav>`
// 剥块:任意版本的 ddd-backnav 块都认,/g 剥净(旧 gen 可能把默认块叠进已含当前块的 demo,单发正则剥不净)。
// 块文法收紧为完整模板形制(注释→style→带 id 的 nav;手工只改过 <a>/ctx 不改结构):防 <pre> 里只贴注释行的
// 原文示例被「注释→就近 </nav>」的松匹配误卷。已知边界:样例若把整块(注释+style+带真 nav id 的 nav)逐字节
// 贴全,仍会被当真块剥掉——讲 backnav 机制的 demo 请至少转义 nav id。
const BACKNAV_BLOCK_RE = /\n?<!-- ddd-backnav v[0-9]+ -->\n<style[^>]*>[\s\S]*?<\/style>\n<nav\b[^>]*\bid="ddd-backnav"[\s\S]*?<\/nav>/g
const BACKNAV_MARK = `<!-- ${BACKNAV_VER} -->` // 闭合到 --> 才算命中当前版,防将来 v30 撞 v3 前缀
// 换章保手工件:旧块里手工改过的返回链/ctx 注记(非默认件)原样携带进新章,默认件才随模板走。
// 有 demo 会手工调返回栏(自定义回跳锚、真数据注记等);整块重置会把这些手工件误标回默认——伤信任,不做。
const BACKNAV_A_DEF = '<a href="../index.html#decisions">← 返回看板</a>'
const BACKNAV_CTX_DEFS = new Set([`${esc(BRAND)} Demo · mock 数据`]) // 当前 brand 默认 ctx
const backnavCustom = (blk) => {
  const nav = blk.match(/<nav [^>]*>([\s\S]*)<\/nav>/)
  const a = nav && nav[1].match(/<a [^>]*>[\s\S]*?<\/a>/)
  const ctx = nav && nav[1].match(/<span class="ctx">([\s\S]*?)<\/span>/)
  return {
    a: a && a[0] !== BACKNAV_A_DEF ? a[0] : null,
    ctx: ctx && !BACKNAV_CTX_DEFS.has(ctx[1]) ? ctx[0] : null,
  }
}

function injectDemoBacknav() {
  let files = []
  try { files = readdirSync(DEMOS_DIR).filter((f) => f.toLowerCase().endsWith('.html')) } catch { return }
  let injected = 0, upgraded = 0, skipped = 0
  for (const f of files) {
    const p = join(DEMOS_DIR, f)
    let html = readFileSync(p, 'utf8')
    const blocks = [...html.matchAll(BACKNAV_BLOCK_RE)].map((m) => m[0])
    // 新鲜 = 恰一块且是当前版;「含当前版但叠着他版残块」(旧 gen 盖板事故)与同版双块(并发/坏合并)都重整
    if (blocks.length === 1 && blocks[0].includes(BACKNAV_MARK)) { skipped++; continue }
    // 手工件回捞优先级:当前版∧有手工件 > 当前版 > 有手工件 > 首块——旧 gen 把 v2 默认块插在
    // v3 块上方,取首块会把手工注记误标回默认;同版双块时默认块也可能在上,故手工件再前置一档
    const hasCustom = (b) => { const c = backnavCustom(b); return Boolean(c.a || c.ctx) }
    const src = blocks.find((b) => b.includes(BACKNAV_MARK) && hasCustom(b))
      || blocks.find((b) => b.includes(BACKNAV_MARK))
      || blocks.find(hasCustom)
      || blocks[0]
    let block = BACKNAV_BLOCK
    if (src) {
      const { a, ctx } = backnavCustom(src) // replace 用函数形式防 $ 特殊序列
      if (a) block = block.replace(BACKNAV_A_DEF, () => a)
      if (ctx) block = block.replace(/<span class="ctx">[\s\S]*?<\/span>/, () => ctx)
    }
    html = html.replace(BACKNAV_BLOCK_RE, '')
    if (!/<body[^>]*>/.test(html)) { console.warn(`[gen] ⚠ demo ${f} 无 <body>,跳过`); continue }
    writeFileSync(p, html.replace(/<body[^>]*>/, (bTag) => `${bTag}\n${block}`), 'utf8')
    blocks.length ? upgraded++ : injected++
  }
  console.log(`[gen] ↩ demo 返回栏:注入 ${injected} · 升级 ${upgraded}(${skipped} 已是当前版)`)
}

// ============================================================================
//  零依赖 markdown → HTML 渲染器(移植自 A 线 decision-map/gen.mjs)
// ============================================================================
function makeSlugger() {
  const used = new Set()
  let sec = 0
  return function slug(rawText) {
    const adr = rawText.match(/^ADR-(\d+)/i)
    const dq = rawText.match(/^([DQ])-?(\d+)\b/i)
    let base
    if (adr) base = 'adr-' + adr[1]
    else if (dq) base = dq[1].toLowerCase() + '-' + dq[2]
    else {
      base = rawText.toLowerCase().replace(/`[^`]*`/g, ' ').replace(/[*~_]/g, '')
        .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
      if (!base) base = 'sec-' + ++sec
    }
    let s = base, n = 2
    while (used.has(s)) s = base + '-' + n++
    used.add(s)
    return s
  }
}

// 文档内链接重写:已渲染文档 → 同目录 basename;代码/数据 → GitHub blob;否则不可点 span。
function makeRelinker(baseDir) {
  return function (rawHref) {
    let href = String(rawHref).trim()
    if (/^(https?:|mailto:|tel:)/i.test(href)) return { href, external: true }
    if (href.startsWith('#')) return { href }
    let frag = ''
    const h = href.indexOf('#')
    if (h >= 0) { frag = href.slice(h); href = href.slice(0, h) }
    if (!href) return { href: frag || '#' }
    const repoPath = resolveRepoPath(baseDir, href)
    if (RENDERED[repoPath]) return { href: RENDERED[repoPath] + frag }
    if (CODE_EXT.test(repoPath)) return { href: GH_BLOB + repoPath + frag, external: true }
    return { dead: true, repoPath }
  }
}

function inlineMd(text, relink) {
  const codes = []
  let t = String(text).replace(/`([^`\n]+)`/g, (mm, body) => { codes.push(body); return '\u0000' + (codes.length - 1) + '\u0000' })
  t = t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  t = t.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (mm, txt, href) => {
    const r = relink(href)
    if (r.dead) return '<span class="ref-dead" title="未渲染引用:' + esc(r.repoPath) + '">' + txt + '</span>'
    const ext = r.external ? ' target="_blank" rel="noopener"' : ''
    return '<a href="' + esc(r.href) + '"' + ext + '>' + txt + '</a>'
  })
  t = t.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
  t = t.replace(/~~([^~]+)~~/g, '<del>$1</del>')
  t = t.replace(/\*([^*\n]+)\*/g, '<em>$1</em>')
  t = t.replace(/\u0000(\d+)\u0000/g, (mm, n) => '<code>' + esc(codes[+n]) + '</code>')
  return t
}

const isTableSep = (s) => /\|/.test(s) && /^[\s|:\-]+$/.test(s) && /--/.test(s)
const isListLine = (s) => /^\s*([-*+]|\d+[.)])\s+/.test(s)
const isHr = (s) => /^\s*([-*_])\1{2,}\s*$/.test(s) && !s.includes('|')
const isFence = (s) => /^\s*(`{3,}|~{3,})/.test(s)
const isHeading = (s) => /^#{1,6}\s+/.test(s)

function splitRow(s) {
  let t = s.trim()
  if (t.startsWith('|')) t = t.slice(1)
  if (t.endsWith('|')) t = t.slice(0, -1)
  return t.split('|').map((c) => c.trim())
}

function renderListSiblings(items, lo, hi, inline) {
  let html = ''
  let j = lo
  while (j < hi) {
    const ordered = items[j].ordered
    const tag = ordered ? 'ol' : 'ul'
    html += '<' + tag + '>'
    while (j < hi && items[j].ordered === ordered) {
      const it = items[j]
      let k = j + 1
      while (k < hi && items[k].indent > it.indent) k++
      html += '<li>' + inline(it.text) + (k > j + 1 ? renderListSiblings(items, j + 1, k, inline) : '') + '</li>'
      j = k
    }
    html += '</' + tag + '>'
  }
  return html
}

function renderQuoteInner(text, inline) {
  return text.split(/\n\s*\n/).filter((p) => p.trim())
    .map((p) => '<p>' + p.split('\n').map(inline).join('<br>') + '</p>').join('')
}

function mdToHtml(src, baseDir) {
  const relink = makeRelinker(baseDir)
  const slug = makeSlugger()
  const inline = (t) => inlineMd(t, relink)
  const headings = []
  const lines = src.replace(/\r\n?/g, '\n').split('\n')
  const out = []
  let warned = 0
  let i = 0
  while (i < lines.length) {
    const line = lines[i]
    const fence = line.match(/^(\s*)(`{3,}|~{3,})(.*)$/)
    if (fence) {
      const ch = fence[2][0], len = fence[2].length
      const lang = (fence[3] || '').trim().split(/\s+/)[0] || ''
      const buf = []
      i++
      while (i < lines.length) {
        const cl = lines[i].match(/^(\s*)(`{3,}|~{3,})\s*$/)
        if (cl && cl[2][0] === ch && cl[2].length >= len) { i++; break }
        buf.push(lines[i]); i++
      }
      const cls = lang ? ' class="language-' + esc(lang) + '"' : ''
      out.push('<pre><code' + cls + '>' + buf.map(esc).join('\n') + '</code></pre>')
      continue
    }
    if (/^\s*$/.test(line)) { i++; continue }
    const h = line.match(/^(#{1,6})\s+(.+?)\s*$/)
    if (h) {
      const level = h[1].length, rawt = h[2], id = slug(rawt)
      headings.push({ level, text: rawt, slug: id })
      out.push('<h' + level + ' id="' + esc(id) + '">' + inline(rawt) + '</h' + level + '>')
      i++; continue
    }
    if (isHr(line)) { out.push('<hr>'); i++; continue }
    if (/^\s*>/.test(line)) {
      const buf = []
      while (i < lines.length && /^\s*>/.test(lines[i])) { buf.push(lines[i].replace(/^\s*>\s?/, '')); i++ }
      try { out.push('<blockquote>' + renderQuoteInner(buf.join('\n'), inline) + '</blockquote>') }
      catch { out.push('<pre class="md-fallback">' + esc(buf.join('\n')) + '</pre>'); warned++ }
      continue
    }
    if (line.includes('|') && i + 1 < lines.length && isTableSep(lines[i + 1])) {
      const start = i
      try {
        const aligns = splitRow(lines[i + 1]).map((c) => {
          const l = c.startsWith(':'), r = c.endsWith(':')
          return l && r ? 'center' : r ? 'right' : l ? 'left' : ''
        })
        const ths = splitRow(lines[i])
        let j = i + 2
        const rows = []
        while (j < lines.length && lines[j].includes('|') && lines[j].trim() && !isFence(lines[j]) && !isHeading(lines[j])) {
          rows.push(splitRow(lines[j])); j++
        }
        const al = (k) => (aligns[k] ? ' style="text-align:' + aligns[k] + '"' : '')
        let tbl = '<table><thead><tr>'
        ths.forEach((c, k) => { tbl += '<th' + al(k) + '>' + inline(c) + '</th>' })
        tbl += '</tr></thead><tbody>'
        rows.forEach((r) => {
          tbl += '<tr>'
          for (let k = 0; k < ths.length; k++) tbl += '<td' + al(k) + '>' + inline(r[k] || '') + '</td>'
          tbl += '</tr>'
        })
        tbl += '</tbody></table>'
        out.push(tbl); i = j
      } catch {
        const buf = []
        let j = start
        while (j < lines.length && lines[j].includes('|') && lines[j].trim()) { buf.push(lines[j]); j++ }
        out.push('<pre class="md-fallback">' + esc(buf.join('\n')) + '</pre>'); i = j; warned++
      }
      continue
    }
    if (isListLine(line)) {
      const start = i
      try {
        const items = []
        while (i < lines.length && isListLine(lines[i])) {
          const mm = lines[i].match(/^(\s*)([-*+]|\d+[.)])\s+(.*)$/)
          items.push({ indent: mm[1].length, ordered: /\d/.test(mm[2]), text: mm[3] }); i++
        }
        out.push(renderListSiblings(items, 0, items.length, inline))
      } catch {
        const buf = []
        let j = start
        while (j < lines.length && isListLine(lines[j])) { buf.push(lines[j]); j++ }
        out.push('<pre class="md-fallback">' + esc(buf.join('\n')) + '</pre>'); i = j; warned++
      }
      continue
    }
    {
      const buf = []
      while (i < lines.length && !/^\s*$/.test(lines[i]) && !isHeading(lines[i]) && !isFence(lines[i]) &&
        !/^\s*>/.test(lines[i]) && !isListLine(lines[i]) && !isHr(lines[i]) &&
        !(lines[i].includes('|') && i + 1 < lines.length && isTableSep(lines[i + 1]))) {
        buf.push(lines[i]); i++
      }
      out.push('<p>' + buf.map(inline).join('<br>') + '</p>')
    }
  }
  return { html: out.join('\n'), headings, warned }
}

