const ACC_D_OF_PR = !ACC ? {} : Object.fromEntries(ACC_LISTS.flatMap((l) => l.nums.map((n) => [String(n), l.key])))
// 数据搬家(v0.15.0):非懒照旧就地烤在 IIFE 里;懒模式下同一份 JSON 随 part 走,注入后读 textContent
// (application/json 不执行,innerHTML 注入照样留得住文本;`<` 仍走 accJson 的 \u003c,`</script` 拼不出来)。
const ACC_DATA_BLOCK = !ACC_LAZY ? '' : `\n  <script type="application/json" id="acc-data">${accJson({ LISTS: ACC_D_LISTS, TSV: ACC_D_TSV, OF_PR: ACC_D_OF_PR })}</script>`
const ACC_PART = !ACC_LAZY ? '' : acceptancePane + ACC_DATA_BLOCK
const ACC_OPEN = !ACC ? '' : (!ACC_LAZY
  ? `;(function () {  // 前置分号:本码库无分号风格(ASI),紧跟在上一句后会被解析成调用,必须挡开
    var LISTS = ${accJson(ACC_D_LISTS)}
    var TSV = ${accJson(ACC_D_TSV)}
    var OF_PR = ${accJson(ACC_D_OF_PR)}`
  : `// 验收 pane 随 parts/acceptance.html 外提,数据跟着走:壳里只留这只初始化函数,注入完跑一次
  var accReady = false
  function initAcceptance(root) {
    if (accReady || !root) return  // 幂等:点 tab、空闲预取、发布表格要分子,三条路都可能到,只认第一次
    accReady = true
    var __ad = JSON.parse(root.querySelector('#acc-data').textContent)
    var LISTS = __ad.LISTS, TSV = __ad.TSV, OF_PR = __ad.OF_PR`)
const ACC_CLOSE = !ACC ? '' : (!ACC_LAZY ? `})();` : `}`)
const ACC_JS = !ACC ? '' : `
  ${ACC_OPEN}
    var byKey = {}, ck = {}, view = {}
    function lsKey(l) { return '${LS_PREFIX}_acc_' + l.k + '_r' + l.rev }
    function load(l) {
      var v = null
      try { var raw = localStorage.getItem(lsKey(l)); if (raw) v = JSON.parse(raw) } catch (e) {}
      if (!v || typeof v !== 'object') { // 首次进来:manifest 里的 result.checked 作初值(记录进 git 的那次验收)
        v = {}
        l.pre.forEach(function (id) { v[id] = true })
        if (l.pre.length) save(l, v)
      }
      return v
    }
    function save(l, v) { try { localStorage.setItem(lsKey(l), JSON.stringify(v)) } catch (e) {} }
    function visible(l, it) {
      var w = view[l.k]
      return (w.round === 'all' || it.rd === w.round) && (w.pr === 'all' || String(it.pr) === w.pr)
    }
    // http 内网页面多半不是安全上下文,navigator.clipboard 不存在 —— 退回 execCommand 老路
    function copyText(t, btn, okmsg) {
      var orig = btn.textContent
      var done = function () {
        btn.textContent = okmsg || '已复制'; btn.classList.add('ok')
        setTimeout(function () { btn.textContent = orig; btn.classList.remove('ok') }, 2000)
      }
      var fallback = function () {
        var ta = document.createElement('textarea')
        ta.value = t; ta.setAttribute('readonly', ''); ta.style.position = 'fixed'; ta.style.top = '-9999px'
        document.body.appendChild(ta); ta.select()
        try { document.execCommand('copy'); done() } catch (e) { btn.textContent = '复制失败,手动选' }
        document.body.removeChild(ta)
      }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(t).then(done, fallback)
      else fallback()
    }
    function syncList(l) {
      var sec = document.getElementById('acc-' + l.k)
      if (!sec) return
      // 行按 id 索引一遍,不拿 id 去拼选择器:条目 id 是人写在清单里的,带个引号就拼出非法选择器,
      // querySelector 当场抛 —— 验收与发布进度共用一个 <script>,一抛后面整块都不跑了。
      var rowsById = new Map()
      sec.querySelectorAll('[data-accid]').forEach(function (r) { rowsById.set(r.dataset.accid, r) })
      var mine = ck[l.k], vt = 0, vd = 0, gc = {}
      l.items.forEach(function (it) {
        var on = Boolean(mine[it.id]), shown = visible(l, it)
        var row = rowsById.get(it.id)
        if (row) {
          row.style.display = shown ? '' : 'none'
          row.classList.toggle('done', on)
          var box = row.querySelector('input')
          if (box) box.checked = on
        }
        if (shown) { vt++; if (on) vd++ }
        gc[it.g] = gc[it.g] || { t: 0, d: 0, v: 0 }
        gc[it.g].t++; if (on) gc[it.g].d++; if (shown) gc[it.g].v++
      })
      sec.querySelectorAll('.accgrp').forEach(function (g) { g.style.display = (gc[g.dataset.accg] || {}).v ? '' : 'none' })
      sec.querySelectorAll('[data-accgl]').forEach(function (a) {
        var c = gc[a.dataset.accgl] || { t: 0, d: 0, v: 0 }
        var n = a.querySelector('.accgc'); if (n) n.textContent = c.d + '/' + c.t
        a.classList.toggle('done', c.t > 0 && c.d === c.t)
        a.style.display = c.v ? '' : 'none'
      })
      var p = document.querySelector('[data-accprog="' + l.k + '"]')
      if (p) { // 进度 = 当前筛选可见条目里的已勾数(筛了轮次就只算那一轮)
        p.querySelector('.accdone').textContent = vd
        p.querySelector('.acctot').textContent = vt
        p.querySelector('.accbar i').style.width = (vt ? vd / vt * 100 : 0) + '%'
      }
    }
    function syncChips() { // 全板卡头的「验收中 · n/N」分子(卡在别的 pane 里也照算)
      document.querySelectorAll('[data-acc]').forEach(function (s) {
        var l = byKey[OF_PR[s.dataset.acc]]
        if (!l) return
        var mine = ck[l.k], d = 0
        l.items.forEach(function (it) { if (mine[it.id]) d++ })
        s.textContent = d + '/' + l.items.length
      })${OV_ACC_BAR}
    }
    function spy() { // 分组目录跟随滚动;滚到底点亮末项(末组太短时永远轮不到它)
      LISTS.forEach(function (l) {
        var sec = document.getElementById('acc-' + l.k)
        if (!sec || !sec.offsetParent) return
        var gs = [].slice.call(sec.querySelectorAll('.accgrp')).filter(function (g) { return g.style.display !== 'none' })
        if (!gs.length) return
        var y = window.scrollY + 96, cur = gs[0]
        for (var i = 0; i < gs.length; i++) { if (gs[i].getBoundingClientRect().top + window.scrollY <= y) cur = gs[i]; else break }
        if (window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 4) cur = gs[gs.length - 1]
        sec.querySelectorAll('[data-accgl]').forEach(function (a) { a.classList.toggle('on', a.dataset.accgl === cur.dataset.accg) })
      })
    }
    window.accSync = function () { LISTS.forEach(syncList); syncChips(); spy() }
    var pane = document.getElementById('pane-acceptance')
    if (pane) {
      pane.addEventListener('click', function (ev) {
        var f = ev.target.closest('.accf button')
        if (f) {
          var l = byKey[f.closest('.acclist').dataset.acck]
          view[l.k][f.closest('.accf').dataset.accf] = f.dataset.v
          f.parentElement.querySelectorAll('button').forEach(function (x) { x.classList.toggle('on', x === f) })
          syncList(l); spy()
          return
        }
        var t = ev.target.closest('[data-acctsv]')
        if (t) { copyText(TSV[t.closest('.acclist').dataset.acck][t.dataset.acctsv], t); return }
        var c = ev.target.closest('[data-acccopy]')
        if (c) {
          var cl = byKey[c.dataset.acccopy], mine = ck[cl.k]
          var checked = cl.items.filter(function (it) { return mine[it.id] }).map(function (it) { return it.id })
          var d = new Date()
          var at = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0')
          copyText(JSON.stringify({ checked: checked, at: at }), c, '已复制 · 贴回清单的 result')
        }
      })
      pane.addEventListener('change', function (ev) {
        var box = ev.target.closest('[data-accck]')
        if (!box) return
        var l = byKey[box.closest('.acclist').dataset.acck]
        if (box.checked) ck[l.k][box.dataset.accck] = true
        else delete ck[l.k][box.dataset.accck]
        save(l, ck[l.k]); syncList(l); syncChips()
      })
    }
    function accRoute() { // #acc-230 深链:目标可能折在 <details> 里,先展开再滚
      var id = decodeURIComponent(location.hash.slice(1))
      if (id.indexOf('acc') !== 0) return
      var el = document.getElementById(id)
      if (!el) return
      for (var p = el.parentElement; p; p = p.parentElement) if (p.tagName === 'DETAILS') p.open = true
      window.accSync()
      el.scrollIntoView({ behavior: 'smooth', block: 'start' })
    }
    LISTS.forEach(function (l) { byKey[l.k] = l; ck[l.k] = load(l); view[l.k] = { round: 'all', pr: 'all' } })
    window.addEventListener('scroll', spy, { passive: true })
    window.addEventListener('hashchange', accRoute)
    window.accSync()
    accRoute()
  ${ACC_CLOSE}`

// ============================================================================
//  发布进度 pane(v0.12.0):release-manifest.json → 三段计数 + 时间线 / 表格两视图
//  REL 关时本节所有产物为空串/空表,index.html 逐字节冻结。
//  gen 零时间:「今天」「同步过时」全在浏览器算;这里只烤入 ISO 原文。
// ============================================================================
const REL_AT = new Map() // 版本 → 打 tag 时刻(排序键:同一版本的行共用它才聚得成块)
const REL_NOTE = new Map()
if (REL) for (const r of rlm.releases || []) if (r && r.tag) { REL_AT.set(String(r.tag), String(r.at || '')); REL_NOTE.set(String(r.tag), String(r.note || '')) }
const REL_LATEST = relSorted.length ? String(relSorted[relSorted.length - 1].tag) : '' // 最新版:默认展开的那组

// PR 号 → 关联卡。gen 现算,不用 pr-sync 写进 prs[].cards 的那份 —— manifest 改过卡就该跟着变,
// 同一口径 prsOfCard(显式 pr ∪ links 兼容),与验收 pane 的关联卡是同一套反查。
const relCardsOfPr = new Map()
if (REL) for (const c of CARD_INDEX) for (const p of prsOfCard(c.e, PR_REPO)) {
  if (p.repo !== PR_REPO) continue
  if (!relCardsOfPr.has(p.num)) relCardsOfPr.set(p.num, [])
  relCardsOfPr.get(p.num).push(c)
}

const REL_ROWS = !REL ? [] : (rlm.prs || []).filter((p) => p && p.number != null).map((p) => {
  const n = Number(p.number)
  return { n, p, sg: stageOf(p, REL_IDX, REL_MAIN, REL_STAGE_IDS), cards: relCardsOfPr.get(n) || [], list: ACC_BY_PR.get(n) || null }
})
const REL_COUNT = { dev: 0, test: 0, prod: 0, other: 0 }
for (const r of REL_ROWS) REL_COUNT[r.sg.id in REL_COUNT ? r.sg.id : 'other']++

const relDate = (r) => String(r.p.mergedAt || r.p.closedAt || r.p.createdAt || '')
// 段优先:开着的 PR 是这张表要盯的正事,不能因为「最新版本的 tag 比它新」就被整块已发的压到底下
// (那样状态·日期那一列读下来还是乱的:已发 08-19 在开着 08-26 上面)。段内才按日期降序。
const relRank = (r) => r.sg.id === 'dev' ? 0 : r.sg.id === 'test' ? 1 : r.sg.id === 'prod' ? 2 : 3
// 段内日期降序;但已归版的行拿「打 tag 时刻」当键 —— 同版共键才保证一版聚成连续一块,
// 否则一个七月合的 PR 会按自己的日期插进 v0.0.2 组中间,分组头就得重复出现。
// 没写 at 的版本退回拿 tag 本身当键(而不是行自己的日期)—— 键只要一版一个常量,同版就还是连续一块。
const relSortKey = (r) => r.sg.tag ? (REL_AT.get(r.sg.tag) || r.sg.tag) : relDate(r)
const relCmp = (a, b) => {
  const ra = relRank(a), rb = relRank(b)
  if (ra !== rb) return ra - rb
  const ka = relSortKey(a), kb = relSortKey(b)
  if (ka !== kb) return ka < kb ? 1 : -1
  if (a.sg.tag !== b.sg.tag) return a.sg.tag < b.sg.tag ? 1 : -1
  const da = relDate(a), db = relDate(b)
  if (da !== db) return da < db ? 1 : -1
  return b.n - a.n
}
const relMd = (s) => String(s || '').slice(5, 10) // ISO → MM-DD(只用于展示)
const REL_LABEL = new Map(REL_STAGES.map((s) => [s.id, s.label]))
const relStageText = (r) => r.sg.id === 'offline' ? '非主线'
  : r.sg.id === 'closed' ? '已关闭'
    : `${REL_LABEL.get(r.sg.id) || r.sg.id}${r.sg.tag ? ` ${r.sg.tag}` : ''}`
const relStatusText = (r) => {
  const p = r.p
  if (p.state === 'open') return `${p.draft ? '草稿' : '开着'} · ${relMd(p.createdAt)}`
  if (p.state === 'closed') return `已关闭 · ${relMd(p.closedAt || p.createdAt)}`
  if (p.state === 'merged') return r.sg.tag ? `已发 ${r.sg.tag} · ${relMd(p.mergedAt)}` : `已合 · ${relMd(p.mergedAt)}`
  return relMd(p.createdAt)
}

// ———— 时间线的带(v0.13.1)————
// 0.12.0 的时间线一 PR 一行:240 个 PR 铺成 2400px 高,横轴几乎空置。改成一版一带:
// 纵向从「PR 数」变成「带数」,展开的带用泳道打包(高度封顶),横向按繁忙度加宽。
// 锚点日 = 开着的按 createdAt、合了的按 mergedAt、关掉的按 closedAt,与表格「状态 · 日期」同口径;
// 每天的锚点数既定轴宽,也定折叠态那一排小竖标的高度。
const relAnchor = (p) => String((p.state === 'open' ? p.createdAt : p.mergedAt || p.closedAt || p.createdAt) || '').slice(0, 10)
// 带 id:prod 按版本拆开,三段之外的(非主线 / 关掉未合)并进「其它」—— 与段芯片同一口径
const relGid = (sg) => sg.id === 'prod' ? sg.tag || 'prod' : sg.id === 'dev' || sg.id === 'test' ? sg.id : 'other'
const REL_GROUPS = !REL ? [] : (() => {
  const rowsOf = new Map()
  for (const r of REL_ROWS) {
    const g = relGid(r.sg)
    if (!rowsOf.has(g)) rowsOf.set(g, [])
    rowsOf.get(g).push(r)
  }
  const out = []
  let vi = 0
  const take = (g, nm, sf, sg) => { // 空带不占一行:一条空带说不出话,而带数就是这个视图的全部预算
    const rs = rowsOf.get(g)
    if (!rs) return
    rowsOf.delete(g)
    const d = {}
    let lo = '', hi = ''
    for (const r of rs) {
      const a = relAnchor(r.p)
      if (!a) continue
      d[a] = (d[a] || 0) + 1
      if (!lo || a < lo) lo = a
      if (!hi || a > hi) hi = a
    }
    // 版本带之间只差一档透明度(看板没有第二套强调色,也不该为这张图新造):最新版最实,越老越淡
    out.push({ g, nm, sf, sg, n: rs.length, lo, hi, d, q: sg === 'prod' ? Math.max(1, 4 - vi++) : 4 })
  }
  for (const s of REL_STAGES) if (s.id === 'dev' || s.id === 'test') take(s.id, s.label, s.hint, s.id)
  for (const r of relSorted.slice().reverse()) take(String(r.tag), String(r.tag), REL_NOTE.get(String(r.tag)) || '', 'prod')
  // 兜底:没写 at 的版本(relSorted 不收它)与「缺 test 的宿主那条无版本 prod」,排在有 at 的版本之后
  for (const g of [...rowsOf.keys()].filter((x) => x !== 'other').sort().reverse()) take(g, g === 'prod' ? REL_LABEL.get('prod') || 'prod' : g, '', 'prod')
  take('other', '其它', '非主线 base 的 PR 与关掉未合的 PR', 'other')
  return out
})()
// 几何(轴 / 刻度 / 泳道 / 带高)原样内联进页面:测试 import 的与页面跑的是同一份源码。
const REL_GEOM_SRC = !REL ? '' : readFileSync(new URL('./relgeom.mjs', import.meta.url), 'utf8')
  .replace(/^export /gm, '').replace(/^(?!$)/gm, '    ')

const relRowHtml = (r) => {
  const p = r.p
  const cur = ACC && Number(acm.current) === r.n
  return `
            <tr class="relr" id="pr-${r.n}" data-relnum="${r.n}">
              <td class="rc-n"><a href="${esc(safeHref(p.url || prUrl({ repo: PR_REPO, num: r.n })))}" target="_blank" rel="noopener">#${r.n}</a></td>
              <td class="rc-t">${esc(p.title || '')}${cur ? '<span class="relnow">验收中</span>' : ''}</td>
              <td class="rc-s"><span class="relsg s-${r.sg.id}">${esc(relStageText(r))}</span></td>
              <td class="rc-d">${esc(relStatusText(r))}</td>
              <td class="rc-k">${r.cards.length ? r.cards.map((c) => `<a class="relcard" href="#${esc(c.id)}" title="${esc(c.title)}">${esc(c.id)}</a>`).join('') : '<span class="relnil">—</span>'}</td>
              <td class="rc-b">${esc(p.branch || '')}${r.sg.id === 'offline' && p.base ? ` <span class="relbase">→ ${esc(p.base)}</span>` : ''}</td>
              <td class="rc-a">${r.list ? `<a class="acclink" href="#acc-${r.n}"><span data-acc="${r.n}">0/${r.list.items.length}</span></a>` : '<span class="relnil">—</span>'}</td>
            </tr>`
}
const relGroupHtml = (tag) => {
  const n = REL_ROWS.filter((x) => x.sg.tag === tag).length
  const at = REL_AT.get(tag) || ''
  const note = REL_NOTE.get(tag) || ''
  const open = tag === REL_LATEST
  return `
            <tr class="relgh" data-relgh="${esc(tag)}"${open ? ' data-relopen="1"' : ''}>
              <td colspan="7"><button type="button" class="relgb"><span class="relgc">${open ? '▾' : '▸'}</span><b>${esc(tag)}</b><span class="relgn"><span class="relgv">${n}</span> 个 PR${at ? ` · ${esc(at.slice(0, 10))}` : ''}</span>${note ? `<span class="relgt">${esc(note)}</span>` : ''}</button></td>
            </tr>`
}
// 表体烤入(而不是运行期生成):#pr-230 深链要在静态 HTML 里就找得到锚,
// 也让「没开 JS / 抓页面 grep」的人看得到全表。运行期只做排序 / 筛选 / 折叠。
const relTableRows = (() => {
  if (!REL) return ''
  const out = []
  const seenGh = new Set() // 一个 tag 只出一次分组头:运行期 ghs 按 tag 索引,多出来的那个永远没人收拾
  let prev = null
  for (const r of REL_ROWS.slice().sort(relCmp)) {
    const g = r.sg.tag
    if (g && g !== prev && !seenGh.has(g)) { out.push(relGroupHtml(g)); seenGh.add(g) }
    prev = g
    out.push(relRowHtml(r))
  }
  return out.join('')
})()

// 待收账段(v0.13.0,定稿 §2.2-2):settle 的卡按 PR 分组。一张没有就整段不渲染 —— 空段比没有更吵。
const relSettleGroups = !REL ? [] : (() => {
  const byPr = new Map()
  for (const c of CARD_INDEX) {
    if (settleHold(c.e)) continue // 挂起的卡不进这段:它已经有人管着,再列一遍就是要人第二次做同一个判断
    const prs = prsOfCard(c.e, PR_REPO)
    if (settleOf(c.e, prs, relPr, PR_REPO).kind !== 'settle') continue
    for (const p of prs) {
      if (p.repo !== PR_REPO || !relPr.has(p.num)) continue
      if (!byPr.has(p.num)) byPr.set(p.num, [])
      byPr.get(p.num).push(c)
    }
  }
  return [...byPr.entries()].sort((a, b) => b[0] - a[0]).map(([n, cards]) => ({ n, cards }))
})()
const relSettleCards = new Set(relSettleGroups.flatMap((g) => g.cards.map((c) => c.id)))
const relSettleHtml = !relSettleGroups.length ? '' : `
  <div class="rspsettle">
    <p class="rspsh">待收账 · ${relSettleCards.size} 张卡<span class="rspsm">PR 都合了,卡还停在非终态。跑 <code>pr-sync.mjs --settle</code> 看清单,确认后 <code>--settle --write</code> 收账。</span></p>${relSettleGroups.map((g) => `
    <p class="rspsr"><a class="prchip" href="${esc(prUrl({ repo: PR_REPO, num: g.n }))}" target="_blank" rel="noopener">PR #${g.n}</a><span class="rspst">${esc((relPr.get(g.n) || {}).title || '')}</span>${g.cards.map((c) => `<a class="relcard" href="#${esc(c.id)}" title="${esc(c.title)}">${esc(c.id)}</a>`).join('')}</p>`).join('')}
  </div>`

const relStageChip = (id, label, n, hint) =>
  `<button type="button" class="relfb" data-relst="${esc(id)}"${hint ? ` title="${esc(hint)}"` : ''}>${esc(label)} <span class="relfn">${n}</span></button>`

const releasePane = !REL ? '' : `
  <div class="topbar">
    <h1>${esc(BRAND)} · 发布进度</h1>
    <span class="sess">数据源 <code>release-manifest.json</code>(<code>pr-sync.mjs</code> 从 <code>gh</code> 同步,gen 只读、不联网)</span>
  </div>
  <div class="relbar">
    <div class="relf" data-relf="stage"><button type="button" class="relfb on" data-relst="all">全部 <span class="relfn">${REL_ROWS.length}</span></button>${REL_STAGES.map((s) => relStageChip(s.id, s.label, REL_COUNT[s.id] || 0, s.hint)).join('')}${REL_COUNT.other ? relStageChip('other', '其它', REL_COUNT.other, '非主线 base 的 PR 与关掉未合的 PR:不属于任何一段') : ''}</div>
    <span class="relsync" data-relsync="${esc(String(rlm.syncedAt || ''))}"></span>
    <span class="relseg" data-relf="view"><button type="button" data-relv="timeline">时间线</button><button type="button" class="on" data-relv="table">表格</button></span>
  </div>
  <div class="relbar2">
    <input type="search" class="relq" placeholder="搜号 / 标题 / 分支 / 卡号" aria-label="搜索 PR">
  </div>${relSettleHtml}${REL_ROWS.length ? '' : `
  <p class="pane-empty" style="display:block">还没有同步过 PR —— 在看板目录跑一次 <code>node &lt;plugin&gt;/scripts/pr-sync.mjs</code>,它会把 <code>gh</code> 看到的 PR 与版本写进 <code>release-manifest.json</code>。</p>`}
  <div class="relview" data-relpane="table">
    <div class="reltw"><div class="reltsc"><table class="relt">
      <thead><tr>
        <th class="relso" data-relsort="n">号 <span class="relar" data-relarr="n"></span></th>
        <th>标题</th>
        <th>段</th>
        <th class="relso" data-relsort="d">状态 · 日期 <span class="relar" data-relarr="d">▾</span></th>
        <th>关联卡</th>
        <th>分支</th>
        <th>验收</th>
      </tr></thead>
      <tbody id="reltb">${relTableRows}
            <tr class="relnone" hidden><td colspan="7">没有匹配的 PR</td></tr>
      </tbody>
    </table></div></div>
  </div>
  <div class="relview" data-relpane="timeline" hidden>
    <div class="relwf"><div class="relf" data-relf="win"><button type="button" class="on" data-relwin="60">近 60 天</button><button type="button" data-relwin="all">全部</button></div><span class="reldrg"></span></div>
    <div class="reltlw"><div class="reltlsc"><div class="reltli" id="reltl"></div></div></div>
    <p class="rellg"><span class="rellk"></span><span class="relmore">横杠 = 开 PR → 合并,虚边 = 还开着;方块 = 当天开当天合,按号横排;竖线 = 版本 tag。轴按当天的繁忙度加宽,安静的日子挤在一起。点带头展开</span></p>
  </div>
  <p class="stamp">由 <code>gen.mjs</code> 生成自 <code>release-manifest.json</code> —— PR 状态与版本由 <code>pr-sync.mjs</code>(调 <code>gh</code>)写入,gen 本身不联网、不取时间;关联卡是每次生成时从三份 manifest 现查的。</p>`

// ———— 发布进度:门控注入片(REL 关时全为空串)————
const REL_TAB = !REL ? '' : `\n    <button class="tab" data-pane="release">发布进度 · ${REL_COUNT.dev}</button>`
// v0.15.0:lazyTabs 开着时发布进度也是一个 part(表格行是这块板上最长的一段标记)
const REL_LAZY = REL && LAZY
const REL_PANE_HTML = !REL ? '' : `\n  <section class="pane" id="pane-release"${REL_LAZY ? ' data-lazy-pending' : ''}>${REL_LAZY ? LAZY_SKEL : releasePane}</section>`
const REL_PANE_ID = !REL ? '' : `, 'release'`
const REL_SHOW = !REL ? '' : `\n    if (name === 'release' && window.relSync) relSync()`
// 懒加载(v0.15.0):发布进度 pane 也是后到的 —— show() 那次 relSync 跑在 fetch 落地之前,注入完当场初始化。
const REL_INJECTED = !REL ? '' : `\n    if (name === 'release') initRelease(document.getElementById('pane-release'))`

// ============================================================================
//  总览 pane(v0.15.0,config.overviewTab)—— B 叙事流:一条流,按「先看什么」排
//  每行 = 一个数据源的一句话 + 可展开的明细;数据源缺席则整行不渲染(空行比没有更吵)。
//  全部派生:manifest / backlog / decisions / acceptance / release + 卡文件更新日,零新数据。
//  gen 零时间的老规矩照旧:天数、7 天窗口、勾选进度全在浏览器算,这里只烤日期与分母。
//  OVERVIEW 关时本节所有产物为空串,index.html 逐字节冻结。
// ============================================================================
const ovRow = ({ k, label, head, tail = '', body, cls = '' }) => `
    <section class="ovrow${cls ? ` ${cls}` : ''}" data-ovrow="${k}">
      <details><summary><span class="ovk">${esc(label)}</span><span class="ovm">${head}</span><span class="ovx">${tail}</span><span class="ovc">▸</span></summary>
      <div class="ovb">${body}</div></details>
    </section>`
const ovCid = (id) => `<a class="ovcid" href="#${esc(id)}">${esc(id)}</a>`
// why 传纯文本就自动包一层 .ovwhy;传 <span class="ovwhy" …> 则原样收下(要挂 data- 属性给运行期用时)
const ovLine = (inner, why = '', attrs = '') => `<div class="ovline"${attrs}>${inner}${!why ? '' : why[0] === '<' ? why : `<span class="ovwhy">${why}</span>`}</div>`
const ovCard = (id, title, why = '', attrs = '') => ovLine(`${ovCid(id)}<span class="ovt">${esc(title)}</span>`, why, attrs)
const ovNil = (t) => `<div class="ovnil">${esc(t)}</div>`

// ① 迭代:manifest 里当前 active 的那个迭代 + 迭代计划链(没有 active 迭代 = 这一行没有话说,不渲染)
const ovIter = !OVERVIEW ? null : iterStats.find((it) => it.state === 'active') || null
const OV_ITER = !ovIter ? '' : ovRow({
  k: 'iter', label: '迭代',
  head: `<b>${esc(ovIter.id)}</b> · ${esc(ovIter.title)}`,
  tail: m.instance.planDoc ? `<a href="${esc(cardLink(m.instance.planDoc).href)}">迭代计划 ↗</a>` : `${ovIter.done}/${ovIter.total}`,
  body: (() => {
    const ts = m.tasks.filter((t) => t.iteration === ovIter.id && (t.status === 'active' || t.status === 'testing'))
    return (ts.length ? ts.map((t) => ovCard(t.id, t.title, esc(m.statuses[t.status] || ''))).join('')
      : ovNil('这个迭代里没有进行中的任务。')) +
      ovNil(`其余 ${iterStats.length - 1} 个迭代的任务表都在页底「迭代史」里,一条没删。`)
  })(),
})

// ② 在验收:acceptance-manifest 的 current 那份清单(分母烤入,分子与进度条由 accSync 在浏览器里算)
const OV_ACC = !OVERVIEW || !ACC ? '' : ACC_CUR ? ovRow({
  k: 'acc', label: '在验收', cls: 'ovacc',
  head: `PR <a class="ovcid" href="#acc-${ACC_CUR.nums[0]}">#${ACC_CUR.nums[0]}</a> · 已试 <b><span data-acc="${ACC_CUR.nums[0]}">0/${ACC_CUR.items.length}</span></b><span class="ovbar"><i></i></span>`,
  tail: `第 ${ACC_CUR.rev} 版清单`,
  body: ovNil(`${ACC_CUR.title || '验收清单'} · ${ACC_CUR.groups.length} 组 ${ACC_CUR.items.length} 条`) +
    accCardsOf(ACC_CUR).slice(0, 6).map((c) => ovCard(c.id, c.title, esc(c.st))).join('') +
    `<div class="ovline"><a class="ovcid" href="#acc-${ACC_CUR.nums[0]}">打开验收清单 ↗</a></div>`,
}) : ovRow({
  k: 'acc', label: '在验收', cls: 'ov-quiet',
  head: '当前没有在验收的 PR',
  tail: ACC_LISTS.length ? `${ACC_LISTS.length} 份清单在册` : '',
  body: ovNil('acceptance-manifest.json 的 current 是 null —— 有 PR 要验收时把号写进去。'),
})

// ③ 可做:与积压提醒(wip)同一个计数,同一套档位色。lanes 开着时随线别重算(见 OV_SETLINE)
const ovReadyCards = !OVERVIEW ? [] : b.items.filter((it) => it.status === 'ready')
const OV_READY_N = ovReadyCards.length
const OV_READY_LV = !OVERVIEW || !WIP ? '' : wipLevel(OV_READY_N)
const OV_READY = !OVERVIEW ? '' : ovRow({
  k: 'ready', label: '可做', cls: OV_READY_LV ? `ov-${OV_READY_LV}` : '',
  head: `<b><span id="ovreadyn">${OV_READY_N}</span></b> 张 ready`,
  tail: `<a href="#backlog">Backlog ↗</a>`,
  body: (() => {
    const top = ovReadyCards.slice().sort((a, b) => { // 积压最久的排前面(没写日期的垫底)
      const x = String(a.date || '9999-99-99'), y = String(b.date || '9999-99-99')
      return x < y ? -1 : x > y ? 1 : 0
    })
    const withPr = ovReadyCards.filter((it) => prsOfCard(it, PR_REPO).length).length
    return (withPr ? ovNil(`其中 ${withPr} 张已开 PR。`) : '') +
      top.slice(0, 6).map((it) => ovCard(it.id, it.title, `<span class="ovwhy" data-ovage="${esc(String(it.date || ''))}"></span>`)).join('') +
      (top.length > 6 ? ovNil(`…另 ${top.length - 6} 张`) : '')
  })(),
})

// ④ 待收账 / 挂起:与卡头琥珀芯片、守卫、pr-sync --settle 同一份 settleOf 口径(挂起的单列,不混进数)
const ovHold = !OVERVIEW || !REL ? [] : CARD_INDEX.filter((c) => settleHold(c.e))
const OV_SETTLE = !OVERVIEW || !REL ? '' : ovRow({
  k: 'settle', label: '待收账', cls: relSettleCards.size ? '' : 'ov-quiet',
  head: `<b>${relSettleCards.size}</b> 张${ovHold.length ? ` · 挂起 <b>${ovHold.length}</b> 张` : ''}`,
  tail: `<a href="#release">发布进度 ↗</a>`,
  body: (relSettleGroups.length
    ? relSettleGroups.map((g) => ovLine(`<a class="ovcid" href="${esc(prUrl({ repo: PR_REPO, num: g.n }))}" target="_blank" rel="noopener">PR #${g.n}</a><span class="ovt">${g.cards.map((c) => `${ovCid(c.id)} `).join('')}</span>`)).join('')
    : ovNil('没有卡等着收账 —— PR 全合而卡未收终态的情况,当前为零。')) +
    (ovHold.length ? ovNil('挂起中(卡上写了 settleHold,看板与守卫都闭嘴):') +
      ovHold.map((c) => ovCard(c.id, c.title, esc(settleHold(c.e)))).join('') : ''),
})

// ⑤ 沉睡:ready + 一个 PR 都没挂 + 超 RESP_DORM 天没动;gen 只烤日期,天数与筛选在浏览器
const ovDormCards = !OVERVIEW || !RESP ? [] : b.items
  .map((it) => ({ it, d: (CARDS_DIR && cardUpd(it.id)) || dormantDate(it) }))
  .filter((x) => dormantDate(x.it) && x.d && !prsOfCard(x.it, PR_REPO).length)
const OV_DORM = !OVERVIEW || !RESP ? '' : ovRow({
  k: 'dorm', label: '沉睡',
  head: `<b><span data-ovdormn>—</span></b> 张`,
  tail: `ready · 无 PR · 超 ${RESP_DORM} 天没动`,
  body: ovDormCards.map((x) => ovCard(x.it.id, x.it.title, '<span class="ovwhy"></span>', ` data-dorm="${esc(x.d)}" hidden`).replace('class="ovline"', 'class="ovline ovdormrow"')).join('') +
    `<div class="ovnil ovdormnil" hidden>没有沉睡的卡。</div>`,
})

// ⑥ 近 7 天动过的卡:更新日 = 卡文件最后提交日(cardsDir 开才有这个事实);窗口在浏览器里算。
// 超出 OV_RECENT_MAX 的不逐张烤,只烤「日期:张数」的游程 —— 日期已降序,「近 7 天还有几张」是个前缀和。
const ovUpd = !OVERVIEW || !CARDS_DIR ? [] : [...m.tasks, ...b.items, ...dm.entries]
  .map((c) => ({ id: String(c.id), title: String(c.title || ''), d: cardUpd(c.id) }))
  .filter((x) => x.d)
  .sort((a, b2) => (a.d < b2.d ? 1 : a.d > b2.d ? -1 : 0))
const OV_RECENT = !OVERVIEW || !CARDS_DIR ? '' : ovRow({
  k: 'recent', label: '近 7 天', cls: 'ov-quiet',
  head: `<b><span data-ovrecn>—</span></b> 张动过`,
  tail: '卡文件最后提交日',
  body: ovUpd.slice(0, OV_RECENT_MAX).map((x) => ovCard(x.id, x.title, esc(x.d.slice(5)), ` data-upd="${esc(x.d)}" hidden`).replace('class="ovline"', 'class="ovline ovrecrow"')).join('') +
    `<span class="ovrest" data-ovrest="${esc((() => {
      const out = []
      for (const x of ovUpd.slice(OV_RECENT_MAX)) {
        const last = out[out.length - 1]
        if (last && last[0] === x.d) last[1]++
        else out.push([x.d, 1])
      }
      return out.map(([d, n]) => `${d}:${n}`).join(',')
    })())}" hidden></span>` +
    `<div class="ovnil ovmore" hidden></div>` + `<div class="ovnil ovrecnil" hidden>近 ${OV_RECENT_DAYS} 天没有卡动过。</div>`,
})

// ⑦ 发布:三段计数(prod 带最新版本号),条长按三段里的最大值归一
const ovStageColor = { dev: 'var(--accent)', test: tk('warn-ink'), prod: BRAND_TK }
const OV_REL = !OVERVIEW || !REL ? '' : ovRow({
  k: 'rel', label: '发布',
  head: REL_STAGES.map((s) => `${esc(s.id)} <b>${REL_COUNT[s.id] || 0}</b>`).join(' / ') + (REL_LATEST ? ` · 最新 ${esc(REL_LATEST)}` : ''),
  tail: `<a href="#release">发布进度 ↗</a>`,
  body: (() => {
    const mx = Math.max(1, ...REL_STAGES.map((s) => REL_COUNT[s.id] || 0))
    const bars = REL_STAGES.map((s) => {
      const n = REL_COUNT[s.id] || 0
      return `<div class="ovstg" style="--c:${escC(ovStageColor[s.id] || 'var(--mut)')}"><span class="ovsn">${esc(s.label)}${s.hint ? ` · ${esc(s.hint)}` : ''}</span><span class="ovsb"><i style="width:${Math.round(n / mx * 100)}%"></i></span><span class="ovsv">${n}</span></div>`
    }).join('')
    const open = REL_ROWS.filter((r) => r.sg.id === 'dev').slice(0, 6)
    return bars + (open.length ? ovNil('开着的:') + open.map((r) => ovLine(`<a class="ovcid" href="${esc(prUrl({ repo: PR_REPO, num: r.n }))}" target="_blank" rel="noopener">#${r.n}</a><span class="ovt">${esc(String(r.p.title || ''))}</span>`)).join('') : '')
  })(),
})

// ⑧ 迭代史:原「进度看板」整块折在页底,一条没删;深链落进折叠内时 routeHash 先把它打开(OV_ROUTE)
const OV_HIST = !OVERVIEW ? '' : `
  <details class="iterhist">
    <summary>迭代史 · ${iterStats.length} 个迭代 · ${m.tasks.length} 个任务<span class="ovhs">原「进度看板」整块折在这里,任务卡深链照旧可达</span></summary>
    <div class="ovhist">${progressPane}</div>
  </details>`

const overviewPane = !OVERVIEW ? '' : `
  <div class="topbar">
    <h1>${esc(m.instance.label || BRAND + ' · 开发进度')}</h1>
    <span class="sess">${esc(m.instance.session)}</span>
    <span class="branch">branch: ${esc(m.instance.branch)}</span>
  </div>
  <div class="ovflow">${OV_ITER}${OV_ACC}${OV_READY}${OV_SETTLE}${OV_DORM}${OV_RECENT}${OV_REL}
  </div>${OV_HIST}
  <p class="stamp">全部由现有 manifest 与卡文件派生,不新增数据源;天数、7 天窗口与勾选进度都在浏览器里算。</p>`

// 颜色只用既有变量与既有令牌(琥珀走 warn 一族、红沿用 wipbar 的 #d44c47),暗档由 darkStyle 统一包 light-dark()
const OV_CSS = !OVERVIEW ? '' : `
  /* ============ 总览(v0.15.0,config.overviewTab)============ */
  .ovflow { border: 1px solid var(--line); border-radius: 12px; background: var(--card); overflow: hidden; margin: 14px 0 0; }
  .ovrow { border-bottom: 1px solid var(--line); }
  .ovrow:last-child { border-bottom: 0; }
  .ovrow > details > summary { list-style: none; cursor: pointer; display: flex; align-items: baseline; gap: 11px;
     padding: 11px 15px; font-size: 13.5px; }
  .ovrow > details > summary::-webkit-details-marker { display: none; }
  .ovrow > details > summary:hover { background: var(--bg); }
  .ovk { flex: none; width: 74px; font-size: 11.5px; color: var(--faint); }
  /* 摘要是一句话:行内文字与 <b> 混排,不做 flex —— flex 容器会把裸文字切成一个个 flex item,
     「dev 4 / test 9」当场被 gap 拆散。进度条走 inline-block 跟着文字走。 */
  .ovm { flex: 1; min-width: 0; }
  .ovm b { font-weight: 650; font-variant-numeric: tabular-nums; }
  .ovx { flex: none; color: var(--mut); font-size: 12.5px; }
  .ovx a, .ovcid { color: var(--accent); text-decoration: none; }
  .ovx a:hover, .ovcid:hover { text-decoration: underline; }
  .ovc { flex: none; color: var(--faint); font-size: 10px; transition: transform .14s ease; }
  .ovrow > details[open] .ovc { transform: rotate(90deg); }
  .ovb { padding: 2px 15px 14px 100px; font-size: 12.5px; }
  .ovrow.ov-soft .ovm b { color: ${tk('warn-ink')}; }
  .ovrow.ov-hard .ovm b { color: #d44c47; }
  .ovrow.ov-quiet .ovm { color: var(--mut); }
  .ovbar { display: inline-block; vertical-align: middle; width: 120px; height: 6px; margin-left: 5px;
     border-radius: 99px; background: var(--line-strong); overflow: hidden; }
  .ovbar > i { display: block; width: 0; height: 100%; border-radius: 99px; background: ${BRAND_TK}; }
  .ovline { display: flex; gap: 9px; align-items: baseline; padding: 4px 0; border-top: 1px dashed var(--line); }
  .ovline:first-child { border-top: 0; }
  .ovcid { flex: none; font-variant-numeric: tabular-nums; }
  .ovt { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .ovwhy { flex: none; color: var(--faint); font-size: 11.5px; }
  .ovnil { color: var(--faint); padding: 4px 0; }
  .ovstg { display: flex; align-items: center; gap: 9px; padding: 5px 0; }
  .ovstg .ovsn { flex: none; width: 128px; color: var(--mut); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .ovstg .ovsb { flex: 1; height: 8px; border-radius: 99px; background: var(--line-strong); overflow: hidden; }
  .ovstg .ovsb > i { display: block; height: 100%; border-radius: 99px; background: var(--c); }
  .ovstg .ovsv { flex: none; width: 34px; text-align: right; font-weight: 600; font-variant-numeric: tabular-nums; }
  .iterhist { margin: 18px 0 0; border-top: 1px solid var(--line); padding-top: 12px; }
  .iterhist > summary { list-style: none; cursor: pointer; font-size: 13px; font-weight: 600; color: var(--mut); }
  .iterhist > summary::-webkit-details-marker { display: none; }
  .iterhist > summary::before { content: "▸ "; font-size: 10px; }
  .iterhist[open] > summary::before { content: "▾ "; }
  .ovhs { margin-left: 9px; font-weight: 400; font-size: 11.5px; color: var(--faint); }
  .ovhist .topbar h1 { font-size: 17px; }
  @media (max-width: 720px) {
    .ovrow > details > summary { flex-wrap: wrap; }
    .ovk { width: auto; }
    .ovb { padding-left: 15px; }
    .ovstg .ovsn { width: 92px; }
  }`

// 相对天数一律浏览器算(gen 零时间是硬纪律);沉睡阈值与卡头芯片同一个常数
const OV_JS = !OVERVIEW ? '' : `
  ;(function () {  // 前置分号:本码库无分号风格(ASI),紧跟在上一句后会被解析成调用,必须挡开
    var ovPane = document.getElementById('pane-progress')
    if (!ovPane) return
    function ovDays(s) { var t = Date.parse(String(s) + 'T00:00:00'); return isFinite(t) ? Math.floor((Date.now() - t) / 86400000) : null }
    function ovText(sel, v) { var el = ovPane.querySelector(sel); if (el) el.textContent = String(v) }
    function ovAges() { // 「积压了几天」:gen 只烤建卡日
      ovPane.querySelectorAll('[data-ovage]').forEach(function (el) {
        var d = ovDays(el.getAttribute('data-ovage'))
        el.textContent = d === null ? '' : d + ' 天'
      })
    }
    function ovDorm() { // 沉睡:超 ${RESP_DORM} 天才现身,数也才算数
      var n = 0
      ovPane.querySelectorAll('.ovdormrow').forEach(function (row) {
        var d = ovDays(row.getAttribute('data-dorm'))
        var on = d !== null && d > ${RESP_DORM}
        row.hidden = !on
        if (on) { n++; var w = row.querySelector('.ovwhy'); if (w) w.textContent = d + ' 天没动' }
      })
      ovText('[data-ovdormn]', n)
      var nil = ovPane.querySelector('.ovdormnil'); if (nil) nil.hidden = n > 0
    }
    function ovRecent() { // 近 ${OV_RECENT_DAYS} 天:列最近 ${OV_RECENT_MAX} 张,更远的只报个数(游程表里数)
      var n = 0
      ovPane.querySelectorAll('.ovrecrow').forEach(function (row) {
        var d = ovDays(row.getAttribute('data-upd'))
        var on = d !== null && d <= ${OV_RECENT_DAYS}
        row.hidden = !on
        if (on) n++
      })
      var rest = 0, box = ovPane.querySelector('.ovrest')
      if (box) String(box.getAttribute('data-ovrest') || '').split(',').filter(Boolean).forEach(function (p) {
        var kv = p.split(':'), d = ovDays(kv[0])
        if (d !== null && d <= ${OV_RECENT_DAYS}) rest += Number(kv[1]) || 0
      })
      ovText('[data-ovrecn]', n + rest)
      var more = ovPane.querySelector('.ovmore')
      if (more) { more.hidden = !rest; more.textContent = '还有 ' + rest + ' 张(这里只列最近 ${OV_RECENT_MAX} 张)' }
      var nil = ovPane.querySelector('.ovrecnil'); if (nil) nil.hidden = (n + rest) > 0
    }
    ovAges(); ovDorm(); ovRecent()
  })()`

// 「可做」随线别/筛选重算:与积压提醒数同一个可见谓词(nVis 是 setLine 内的局部函数)
